(()=>{'use strict';const rows=[["The formulas are correct, but the atom counts are not equal yet.","الصيغ صحيحة، لكن أعداد الذرات ليست متساوية بعد.","הנוסחאות נכונות, אך מספרי האטומים עדיין אינם שווים."],["Why does this matter?","لماذا هذا مهم؟","למה זה חשוב?"],["A chemical equation is a model of what happens in a reaction. Before balancing, the formulas identify the substances involved; balancing then makes the atom counts agree with conservation of mass.","المعادلة الكيميائية نموذج لما يحدث في التفاعل. قبل الموازنة، تحدد الصيغ المواد المشاركة؛ ثم تجعل الموازنة أعداد الذرات متوافقة مع قانون حفظ الكتلة.","משוואה כימית היא מודל למה שמתרחש בתגובה. לפני האיזון הנוסחאות מזהות את החומרים המעורבים; האיזון משווה את מספרי האטומים בהתאם לחוק שימור המסה."],["What does the arrow in a chemical equation show?","ماذا يوضّح السهم في المعادلة الكيميائية؟","מה מראה החץ במשוואה כימית?"],["What are the substances on the left called?","ماذا تُسمّى المواد الموجودة على اليسار؟","כיצד נקראים החומרים שבצד שמאל?"],["What are the substances on the right called?","ماذا تُسمّى المواد الموجودة على اليمين؟","כיצד נקראים החומרים שבצד ימין?"],["Why can't we change the subscript?","لماذا لا يمكننا تغيير الرقم السفلي؟","למה אסור לשנות את המספר התחתון?"],["H₂O and H₂O₂ are different substances. Changing the coefficient changes the amount of a substance; changing the subscript changes the substance itself.","H₂O وH₂O₂ مادتان مختلفتان. تغيير المعامل يغيّر كمية المادة، أما تغيير الرقم السفلي فيغيّر المادة نفسها.","H₂O ו-H₂O₂ הם חומרים שונים. שינוי המקדם משנה את כמות החומר, ואילו שינוי המספר התחתון משנה את החומר עצמו."],["How many oxygen atoms are in Ca(OH)₂?","كم ذرة أكسجين توجد في Ca(OH)₂؟","כמה אטומי חמצן יש ב-Ca(OH)₂?"],["How many hydrogen atoms are in 3H₂O?","كم ذرة هيدروجين توجد في 3H₂O؟","כמה אטומי מימן יש ב-3H₂O?"],["What does the coefficient in 3H₂O multiply?","ما الذي يضربه المعامل في 3H₂O؟","במה מכפיל המקדם ב-3H₂O?"],["Why should a subscript not be changed while balancing?","لماذا يجب عدم تغيير الرقم السفلي أثناء الموازنة؟","למה אין לשנות מספר תחתון בזמן איזון?"],["Count hydrogen: the left side has 4 H atoms and the right side has 4 H atoms. Count oxygen: the left side has 2 O atoms and the right side has 2 O atoms. The equation is balanced.","عدّ الهيدروجين: يحتوي الطرف الأيسر على 4 ذرات H والطرف الأيمن على 4 ذرات H. وعدّ الأكسجين: يحتوي كل طرف على ذرتَي O. لذلك فالمعادلة موزونة.","סופרים מימן: בצד שמאל יש 4 אטומי H ובצד ימין 4. סופרים חמצן: בכל צד יש 2 אטומי O. לכן המשוואה מאוזנת."],["Changing a coefficient changes only how much of a substance participates. That lets us change atom totals while keeping the chemical identities unchanged.","يغيّر المعامل كمية المادة المشاركة فقط. وهكذا يمكن تغيير مجموع الذرات مع إبقاء هوية المواد الكيميائية دون تغيير.","שינוי מקדם משנה רק את כמות החומר המשתתפת. כך אפשר לשנות את מספר האטומים בלי לשנות את הזהות הכימית של החומרים."],["Why must each element have the same atom count on both sides?","لماذا يجب أن يكون عدد ذرات كل عنصر متساويًا في الطرفين؟","למה מספר האטומים של כל יסוד חייב להיות שווה בשני הצדדים?"],["How many H atoms are in 2H₂?","كم ذرة H توجد في 2H₂؟","כמה אטומי H יש ב-2H₂?"],["How many O atoms are in 2H₂O?","كم ذرة O توجد في 2H₂O؟","כמה אטומי O יש ב-2H₂O?"],["Is H₂ + O₂ → H₂O balanced? Explain by counting atoms.","هل المعادلة H₂ + O₂ → H₂O موزونة؟ وضّح ذلك بعدّ الذرات.","האם H₂ + O₂ → H₂O מאוזנת? הסבירו באמצעות ספירת האטומים."],["Use a reliable step-by-step method","استخدم طريقة موثوقة خطوة بخطوة","השתמשו בשיטה אמינה שלב אחר שלב"],["Balancing is not about changing the substances. It is about finding coefficients that make the number of atoms of every element equal on both sides.","لا تتعلق الموازنة بتغيير المواد، بل بإيجاد معاملات تجعل عدد ذرات كل عنصر متساويًا في الطرفين.","איזון אינו שינוי החומרים, אלא מציאת מקדמים שמשווים את מספר האטומים של כל יסוד בשני הצדדים."],["Step 1 — Write the correct formulas","الخطوة 1 — اكتب الصيغ الصحيحة","שלב 1 — כתבו את הנוסחאות הנכונות"],["Make sure every element symbol and chemical formula is correct before balancing. Remember that capitalization matters: Co is cobalt, while CO represents carbon monoxide.","تأكد من صحة رموز العناصر والصيغ الكيميائية قبل الموازنة. انتبه إلى حالة الأحرف: Co هو الكوبالت، أما CO فهو أول أكسيد الكربون.","ודאו שסמלי היסודות והנוסחאות נכונים לפני האיזון. אותיות גדולות וקטנות חשובות: Co הוא קובלט ואילו CO הוא פחמן חד-חמצני."],["Step 2 — Count every atom","الخطوة 2 — عدّ كل ذرة","שלב 2 — ספרו כל אטום"],["Write down the number of atoms of each element on the reactant side and product side.","اكتب عدد ذرات كل عنصر في طرف المتفاعلات وطرف النواتج.","רשמו את מספר האטומים של כל יסוד בצד המגיבים ובצד התוצרים."],["Step 3 — Add coefficients","الخطوة 3 — أضف المعاملات","שלב 3 — הוסיפו מקדמים"],["Place whole-number coefficients in front of formulas. Do not change subscripts.","ضع معاملات صحيحة أمام الصيغ. لا تغيّر الأرقام السفلية.","הוסיפו מקדמים שלמים לפני הנוסחאות. אל תשנו מספרים תחתיים."],["Step 4 — Recount all elements","الخطوة 4 — أعد عدّ جميع العناصر","שלב 4 — ספרו מחדש את כל היסודות"],["After every change, count the atoms again.","أعد عدّ الذرات بعد كل تغيير.","ספרו מחדש את האטומים אחרי כל שינוי."],["Step 5 — Check the final equation","الخطوة 5 — تحقّق من المعادلة النهائية","שלב 5 — בדקו את המשוואה הסופית"],["Make sure every element has exactly the same number of atoms on both sides and that the coefficients are in the smallest whole-number ratio.","تأكد من تساوي عدد ذرات كل عنصر تمامًا في الطرفين، ومن أن المعاملات في أبسط نسبة من الأعداد الصحيحة.","ודאו שמספר האטומים של כל יסוד שווה בדיוק בשני הצדדים ושהמקדמים ביחס השלם הקטן ביותר."],["Put 2 before H₂O.","ضع 2 قبل H₂O.","הוסיפו 2 לפני H₂O."],["Put 2 before H₂.","ضع 2 قبل H₂.","הוסיפו 2 לפני H₂."],["Each coefficient multiplies the entire formula. That is why 2H₂O means two water molecules (or formula units), giving 4 H atoms and 2 O atoms without changing water into a different substance.","يضرب كل معامل الصيغة كاملة. لذلك تعني 2H₂O جزيئَي ماء، أي 4 ذرات H وذرتَي O، دون تحويل الماء إلى مادة أخرى.","כל מקדם מכפיל את הנוסחה כולה. לכן 2H₂O פירושו שתי מולקולות מים, כלומר 4 אטומי H ו-2 אטומי O, בלי להפוך את המים לחומר אחר."],["05 · DIATOMIC ELEMENTS","05 · العناصر ثنائية الذرة","05 · יסודות דו-אטומיים"],["These seven elements occur naturally as diatomic molecules when they are free elements.","توجد هذه العناصر السبعة طبيعيًا على هيئة جزيئات ثنائية الذرة عندما تكون عناصر حرة.","שבעת היסודות האלה מופיעים בדרך כלל כמולקולות דו-אטומיות כשהם יסודות חופשיים."],["When a diatomic element appears by itself in a chemical equation, write it as X₂ rather than as a single X atom.","عندما يظهر عنصر ثنائي الذرة منفردًا في معادلة كيميائية، فاكتبه X₂ بدلًا من ذرة X واحدة.","כאשר יסוד דו-אטומי מופיע לבדו במשוואה כימית, כתבו X₂ ולא אטום X יחיד."],["Which formula represents elemental oxygen?","أي صيغة تمثل الأكسجين العنصري؟","איזו נוסחה מייצגת חמצן יסודי?"],["Which formula represents elemental chlorine?","أي صيغة تمثل الكلور العنصري؟","איזו נוסחה מייצגת כלור יסודי?"],["06 · PUTTING IT ALL TOGETHER","06 · جمع المفاهيم معًا","06 · שילוב כל החומר"],["Balancing checklist","قائمة التحقق من الموازنة","רשימת בדיקה לאיזון"],["✓ Correct element symbols","✓ رموز العناصر صحيحة","✓ סמלי היסודות נכונים"],["✓ Correct chemical formulas and subscripts","✓ الصيغ الكيميائية والأرقام السفلية صحيحة","✓ הנוסחאות והמספרים התחתיים נכונים"],["✓ Correct diatomic formulas when applicable","✓ الصيغ ثنائية الذرة صحيحة عند الحاجة","✓ נוסחאות דו-אטומיות נכונות כשצריך"],["✓ Count atoms on both sides","✓ عدّ الذرات في الطرفين","✓ ספרו אטומים בשני הצדדים"],["✓ Add coefficients instead of changing formulas","✓ أضف معاملات بدلًا من تغيير الصيغ","✓ הוסיפו מקדמים במקום לשנות נוסחאות"],["✓ Recount every element","✓ أعد عدّ كل عنصر","✓ ספרו מחדש כל יסוד"],["✓ Use the smallest whole-number ratio","✓ استخدم أبسط نسبة من الأعداد الصحيحة","✓ השתמשו ביחס השלם הקטן ביותר"],["Final check","التحقق النهائي","בדיקה סופית"],["The final check confirms that every element has the same number of atoms on both sides. If any count differs, the equation is not balanced yet.","يؤكد التحقق النهائي تساوي عدد ذرات كل عنصر في الطرفين. إذا اختلف أي عدد، فالمعادلة لم تتوازن بعد.","הבדיקה הסופית מאשרת שמספר האטומים של כל יסוד שווה בשני הצדדים. אם מספר כלשהו שונה, המשוואה עדיין אינה מאוזנת."],["Build beyond","تجاوزوا","התקדמו מעבר"],["the basics.","الأساسيات.","ליסודות."],["Learn the ideas you need for equations involving groups, parentheses, fractions and more complicated reactions.","تعلّم المفاهيم اللازمة للمعادلات التي تتضمن مجموعات وأقواسًا وكسورًا وتفاعلات أكثر تعقيدًا.","למדו את העקרונות הדרושים למשוואות עם קבוצות, סוגריים, שברים ותגובות מורכבות יותר."],["01 · POLYATOMIC IONS","01 · الأيونات متعددة الذرات","01 · יונים רב-אטומיים"],["Recognize groups that can stay together","تعرّف على المجموعات التي يمكن إبقاؤها معًا","זהו קבוצות שאפשר להשאיר יחד"],["Polyatomic ions are groups of atoms that carry an overall charge, such as SO₄²⁻, NO₃⁻ and OH⁻. In many equations, the same polyatomic ion appears unchanged on both sides. When that happens, treating the group as one unit can make balancing easier.","الأيونات متعددة الذرات مجموعات من الذرات تحمل شحنة كلية، مثل SO₄²⁻ وNO₃⁻ وOH⁻. في كثير من المعادلات يظهر الأيون نفسه دون تغيير في الطرفين، ويمكن عندها التعامل مع المجموعة كوحدة واحدة لتسهيل الموازنة.","יונים רב-אטומיים הם קבוצות אטומים בעלות מטען כולל, כגון SO₄²⁻, NO₃⁻ ו-OH⁻. במשוואות רבות אותו יון מופיע ללא שינוי בשני הצדדים; במקרה כזה אפשר להתייחס לקבוצה כיחידה אחת כדי להקל על האיזון."],["OH and H₂O must still be counted atom by atom when needed. Do not change a subscript inside a chemical formula.","يجب مع ذلك عدّ ذرات OH وH₂O واحدةً واحدة عند الحاجة. لا تغيّر رقمًا سفليًا داخل صيغة كيميائية.","כשצריך, עדיין יש לספור את האטומים ב-OH וב-H₂O בנפרד. אל תשנו מספר תחתון בתוך נוסחה כימית."],["How many oxygen atoms are in 2SO₄?","كم ذرة أكسجين توجد في 2SO₄؟","כמה אטומי חמצן יש ב-2SO₄?"],["What atoms are in NO₃?","ما الذرات الموجودة في NO₃؟","אילו אטומים נמצאים ב-NO₃?"],["Why can an unchanged polyatomic group sometimes be balanced as a unit?","لماذا يمكن أحيانًا موازنة مجموعة متعددة الذرات لم تتغير كوحدة واحدة؟","למה אפשר לפעמים לאזן קבוצה רב-אטומית שלא השתנתה כיחידה אחת?"],["02 · PARENTHESES","02 · الأقواس","02 · סוגריים"],["Count everything inside a group","عدّ كل ما داخل المجموعة","ספרו את כל מה שבתוך הקבוצה"],["A subscript outside parentheses multiplies every atom inside the parentheses.","يضرب الرقم السفلي خارج الأقواس عدد كل ذرة داخل الأقواس.","מספר תחתון מחוץ לסוגריים מכפיל כל אטום שבתוך הסוגריים."],["Ca(OH)₂ contains 1 Ca, 2 O and 2 H. The 2 applies to both O and H.","يحتوي Ca(OH)₂ على ذرة Ca وذرتَي O وذرتَي H. وينطبق الرقم 2 على كل من O وH.","ב-Ca(OH)₂ יש אטום Ca אחד, 2 אטומי O ו-2 אטומי H. המספר 2 חל גם על O וגם על H."],["Al₂(SO₄)₃ contains 2 Al, 3 S and 12 O.","يحتوي Al₂(SO₄)₃ على ذرتَي Al و3 ذرات S و12 ذرة O.","ב-Al₂(SO₄)₃ יש 2 אטומי Al, 3 אטומי S ו-12 אטומי O."],["Count every atom in Mg(OH)₂.","عدّ جميع الذرات في Mg(OH)₂.","ספרו את כל האטומים ב-Mg(OH)₂."],["Count every atom in Al₂(SO₄)₃.","عدّ جميع الذرات في Al₂(SO₄)₃.","ספרו את כל האטומים ב-Al₂(SO₄)₃."],["Why does the 3 outside SO₄ multiply oxygen as well as sulfur?","لماذا يضرب الرقم 3 خارج SO₄ الأكسجين والكبريت معًا؟","למה המספר 3 מחוץ ל-SO₄ מכפיל גם את החמצן וגם את הגופרית?"],["03 · FRACTIONAL COEFFICIENTS","03 · المعاملات الكسرية","03 · מקדמים שבריים"],["Use fractions when they simplify the process","استخدم الكسور عندما تسهّل العملية","השתמשו בשברים כשהם מפשטים את התהליך"],["Sometimes a fractional coefficient is convenient during balancing. Fractions are temporary: after the equation is balanced, multiply every coefficient by the denominator needed to produce the smallest whole-number ratio.","قد يكون استخدام معامل كسري مفيدًا أثناء الموازنة. الكسور مؤقتة: بعد موازنة المعادلة، اضرب كل المعاملات بالمقام اللازم للحصول على أبسط نسبة من الأعداد الصحيحة.","לפעמים מקדם שברי מקל על האיזון. השברים זמניים: לאחר האיזון, הכפילו את כל המקדמים במכנה הדרוש כדי לקבל את היחס השלם הקטן ביותר."],["Multiplying every coefficient by 2 gives:","يؤدي ضرب كل معامل في 2 إلى:","הכפלת כל המקדמים ב-2 נותנת:"],["Why can a fraction be useful while balancing?","لماذا قد يكون الكسر مفيدًا أثناء الموازنة؟","למה שבר יכול להועיל בזמן איזון?"],["What must you do before giving the final answer?","ماذا يجب أن تفعل قبل إعطاء الإجابة النهائية؟","מה צריך לעשות לפני מתן התשובה הסופית?"],["Turn 1/2, 3 and 2 into the smallest whole-number ratio.","حوّل 1/2 و3 و2 إلى أبسط نسبة من الأعداد الصحيحة.","הפכו את 1/2, 3 ו-2 ליחס השלם הקטן ביותר."],["04 · COMPLICATED REACTIONS","04 · تفاعلات معقدة","04 · תגובות מורכבות"],["Choose an order and check repeatedly","اختر ترتيبًا وتحقق مرارًا","בחרו סדר ובדקו שוב ושוב"],["For larger equations, start with an element that appears in fewer formulas. Leave hydrogen and oxygen until later when they occur in many compounds. After each coefficient change, recount every affected element.","في المعادلات الأكبر، ابدأ بعنصر يظهر في عدد أقل من الصيغ. اترك الهيدروجين والأكسجين إلى وقت لاحق عندما يظهران في مركبات كثيرة. أعد عدّ كل عنصر متأثر بعد كل تغيير للمعاملات.","במשוואות גדולות התחילו ביסוד שמופיע בפחות נוסחאות. השאירו את המימן והחמצן לסוף כשישנם בתרכובות רבות. לאחר כל שינוי מקדם, ספרו מחדש כל יסוד שהושפע."],["A useful strategy is to recognize SO₄ as an unchanged group, balance Fe, then OH, then K, and finally verify every element.","من الطرق المفيدة اعتبار SO₄ مجموعة لم تتغير، ثم موازنة Fe وبعده OH ثم K، وأخيرًا التحقق من كل عنصر.","אסטרטגיה שימושית היא לזהות את SO₄ כקבוצה שלא השתנתה, לאזן את Fe, אחר כך את OH ואז את K, ולבסוף לבדוק כל יסוד."],["Which element or group would you balance first and why?","أي عنصر أو مجموعة توازن أولًا، ولماذا؟","איזה יסוד או קבוצה הייתם מאזנים תחילה, ומדוע?"],["How can you verify your final coefficients?","كيف تتحقق من معاملاتك النهائية؟","איך אפשר לוודא את המקדמים הסופיים?"],["01 · COMBUSTION","01 · الاحتراق","01 · בעירה"],["02 · REDOX","02 · الأكسدة والاختزال","02 · חמצון-חיזור"],["03 · COMPLEX IONIC EQUATIONS","03 · معادلات أيونية معقدة","03 · משוואות יוניות מורכבות"],["04 · SYSTEMATIC BALANCING","04 · الموازنة المنهجية","04 · איזון שיטתי"],["Practice Advanced Quiz","اختبار تدريب المستوى المتقدم","תרגול וחידון למתקדמים"],["Back to Learning","العودة إلى التعلّم","חזרה ללמידה"],["Question","السؤال","שאלה"],["Correct","صحيح","נכון"],["Incorrect","غير صحيح","לא נכון"],["Not quite","ليس تمامًا","לא בדיוק"],["The direction from reactants to products.","الاتجاه من المتفاعلات إلى النواتج.","הכיוון מהמגיבים לתוצרים."],["The number of atoms in the reaction.","عدد الذرات في التفاعل.","מספר האטומים בתגובה."],["The temperature of the reaction.","درجة حرارة التفاعل.","טמפרטורת התגובה."],["Reactants.","المتفاعلات.","מגיבים."],["Products.","النواتج.","תוצרים."],["Coefficients.","المعاملات.","מקדמים."],["Subscripts.","الأرقام السفلية.","מספרים תחתיים."],["The entire H₂O formula.","صيغة H₂O كاملةً.","נוסחת H₂O כולה."],["Only the hydrogen atoms.","ذرات الهيدروجين فقط.","אטומי המימן בלבד."],["Only the oxygen atom.","ذرة الأكسجين فقط.","אטום החמצן בלבד."],["It would change the substance.","سيغيّر ذلك المادة نفسها.","הדבר ישנה את החומר."],["It would only change the color of the formula.","سيغيّر لون الصيغة فقط.","הדבר ישנה רק את צבע הנוסחה."],["It would make the equation automatically balanced.","سيجعل المعادلة موزونة تلقائيًا.","הדבר יאזן את המשוואה אוטומטית."],["Atoms are conserved in the reaction.","تُحفَظ الذرات أثناء التفاعل.","האטומים נשמרים במהלך התגובה."],["Every molecule must stay identical.","يجب أن يبقى كل جزيء مطابقًا تمامًا.","כל מולקולה חייבת להישאר זהה."],["Every coefficient must be equal.","يجب أن تكون جميع المعاملات متساوية.","כל המקדמים חייבים להיות שווים."],["No, because oxygen has 2 atoms on the left and 1 on the right.","لا، لأن الطرف الأيسر يحتوي على ذرتَي أكسجين والطرف الأيمن على ذرة واحدة.","לא, כי בצד שמאל יש 2 אטומי חמצן ובצד ימין אטום אחד."],["Yes, because both sides contain H₂O.","نعم، لأن H₂O موجودة في الطرفين.","כן, כי H₂O מופיעה בשני הצדדים."],["Yes, because the coefficients are all 1.","نعم، لأن جميع المعاملات تساوي 1.","כן, כי כל המקדמים הם 1."],["The element symbols and chemical formulas.","رموز العناصر والصيغ الكيميائية.","סמלי היסודות והנוסחאות הכימיות."],["Only the reaction temperature.","درجة حرارة التفاعل فقط.","טמפרטורת התגובה בלבד."],["Only the physical states.","الحالات الفيزيائية فقط.","המצבים הפיזיקליים בלבד."],["New element symbols.","رموز عناصر جديدة.","סמלי יסודות חדשים."],["Recount every element on both sides.","أعد عدّ كل عنصر في الطرفين.","ספרו מחדש כל יסוד בשני הצדדים."],["Change the chemical formulas.","غيّر الصيغ الكيميائية.","שנו את הנוסחאות הכימיות."],["Stop without checking.","توقف دون التحقق.","עצרו בלי לבדוק."],["1 nitrogen and 3 oxygen atoms.","ذرة نيتروجين واحدة و3 ذرات أكسجين.","אטום חנקן אחד ו-3 אטומי חמצן."],["3 nitrogen and 1 oxygen atom.","3 ذرات نيتروجين وذرة أكسجين واحدة.","3 אטומי חנקן ואטום חמצן אחד."],["1 nitrogen and 2 oxygen atoms.","ذرة نيتروجين واحدة وذرتا أكسجين.","אטום חנקן אחד ו-2 אטומי חמצן."],["Its atoms stay together on both sides.","تبقى ذرات المجموعة معًا في الطرفين.","האטומים שלה נשארים יחד בשני הצדדים."],["Its subscripts can be changed freely.","يمكن تغيير أرقامها السفلية بحرية.","אפשר לשנות את המספרים התחתיים שלה בחופשיות."],["It contains only one atom.","تحتوي على ذرة واحدة فقط.","היא מכילה אטום אחד בלבד."],["The 3 applies to the entire SO₄ group.","ينطبق الرقم 3 على مجموعة SO₄ كاملةً.","המספר 3 חל על כל קבוצת SO₄."],["The 3 applies only to sulfur.","ينطبق الرقم 3 على الكبريت فقط.","המספר 3 חל רק על הגופרית."],["Oxygen is not affected by subscripts.","لا تتأثر ذرات الأكسجين بالأرقام السفلية.","מספרים תחתיים אינם משפיעים על החמצן."],["It can make intermediate coefficient relationships easier.","يمكنه تسهيل العلاقات بين المعاملات في الخطوات الوسيطة.","הוא יכול להקל על יחסי המקדמים בשלבי הביניים."],["It changes the chemical formula.","يغيّر الصيغة الكيميائية.","הוא משנה את הנוסחה הכימית."],["It removes the need to conserve atoms.","يلغي الحاجة إلى حفظ الذرات.","הוא מבטל את הצורך בשימור אטומים."],["Clear fractions and reduce to the smallest whole-number ratio.","أزل الكسور واختزل إلى أبسط نسبة من الأعداد الصحيحة.","בטלו את השברים וצמצמו ליחס השלם הקטן ביותר."],["Change the subscripts.","غيّر الأرقام السفلية.","שנו את המספרים התחתיים."],["Leave every fraction unchanged.","اترك كل كسر كما هو.","השאירו כל שבר ללא שינוי."],["SO₄ as an unchanged group.","مجموعة SO₄ دون تغيير.","קבוצת SO₄ שלא השתנתה."],["Hydrogen only.","الهيدروجين فقط.","מימן בלבד."],["Oxygen only.","الأكسجين فقط.","חמצן בלבד."],["Count every element on both sides.","عدّ كل عنصر في الطرفين.","ספרו כל יסוד בשני הצדדים."],["Check only the first element.","تحقق من العنصر الأول فقط.","בדקו רק את היסוד הראשון."],["Check only the largest coefficient.","تحقق من أكبر معامل فقط.","בדקו רק את המקדם הגדול ביותר."],["Carbon.","الكربون.","פחמן."],["Hydrogen.","الهيدروجين.","מימן."],["Oxygen.","الأكسجين.","חמצן."],["It often appears in several products or reactants.","غالبًا ما يظهر في عدة نواتج أو متفاعلات.","הוא מופיע לעיתים קרובות בכמה מגיבים או תוצרים."],["Oxygen cannot be balanced.","لا يمكن موازنة الأكسجين.","אי אפשר לאזן חמצן."],["Oxygen is never part of combustion.","الأكسجين ليس جزءًا من الاحتراق مطلقًا.","חמצן לעולם אינו משתתף בתגובת בעירה."],["Total charge must be conserved.","يجب حفظ الشحنة الكلية.","יש לשמר את המטען הכולל."],["Charge can change without a reaction.","يمكن أن تتغير الشحنة دون حدوث تفاعل.","המטען יכול להשתנות בלי שתתרחש תגובה."],["Only atoms need to be conserved.","يكفي حفظ الذرات فقط.","צריך לשמר רק את האטומים."],["Electric charge is conserved in the reaction.","تُحفَظ الشحنة الكهربائية أثناء التفاعل.","המטען החשמלי נשמר בתגובה."],["Charge is unrelated to ionic equations.","الشحنة لا علاقة لها بالمعادلات الأيونية.","מטען אינו קשור למשוואות יוניות."],["Only oxygen must be conserved.","يجب حفظ الأكسجين فقط.","צריך לשמר רק חמצן."],["Electrons (e⁻).","الإلكترونات (e⁻).","אלקטרונים (e⁻)."],["Water (H₂O).","الماء (H₂O).","מים (H₂O)."],["Oxygen gas (O₂).","غاز الأكسجين (O₂).","גז חמצן (O₂)."],["An unknown coefficient.","معامل مجهول.","מקדם לא ידוע."],["A new subscript.","رقم سفلي جديد.","מספר תחתון חדש."],["A new element symbol.","رمز عنصر جديد.","סמל יסוד חדש."],["They represent amounts of substances.","إنها تمثل كميات المواد.","הם מייצגים כמויות של חומרים."],["Negative amounts are required by conservation.","تتطلب قاعدة الحفظ كميات سالبة.","שימור מחייב כמויות שליליות."],["Positive values change the element symbols.","تغيّر القيم الموجبة رموز العناصر.","ערכים חיוביים משנים את סמלי היסודות."],["To express the simplest whole-number coefficient ratio.","للتعبير عن أبسط نسبة صحيحة للمعاملات.","כדי לבטא את יחס המקדמים השלם הפשוט ביותר."],["To change the substances.","لتغيير المواد.","כדי לשנות את החומרים."],["To remove all coefficients.","لإزالة جميع المعاملات.","כדי להסיר את כל המקדמים."],["Try it here","جرّب هنا","נסו כאן"],["Check your understanding","تحقّق من فهمك","בדקו את הבנתכם"],["Enter a positive whole-number coefficient for every formula.","أدخل معاملًا صحيحًا موجبًا لكل صيغة.","הזינו מקדם שלם וחיובי לכל נוסחה."],["Try again","حاول مرة أخرى","נסו שוב"],["Before you continue","قبل المتابعة","לפני שממשיכים"],["You already passed this precheck.","لقد اجتزت هذا الاختبار المسبق بالفعل.","כבר עברתם את בדיקת הידע המקדים הזאת."],["You can continue without repeating it, or redo the five questions if you want to check yourself again.","يمكنك المتابعة دون إعادته، أو إعادة الأسئلة الخمسة إذا أردت اختبار نفسك مجددًا.","אפשר להמשיך בלי לחזור עליה, או לענות שוב על חמש השאלות כדי לבדוק את עצמכם."],["Questions and answers","الأسئلة والإجابات","שאלות ותשובות"],["Review the five prerequisite questions and the correct answers.","راجع أسئلة المتطلبات السابقة الخمسة وإجاباتها الصحيحة.","עברו על חמש שאלות הידע המקדים והתשובות הנכונות."],["Answer: ","الإجابة: ","תשובה: "],["Redo prerequisite check","أعد اختبار المتطلبات السابقة","בצעו שוב את בדיקת הידע המקדים"],["Continue anyway →","تابع على أي حال ←","המשיכו בכל זאת ←"],["Review","مراجعة","חזרה על החומר"],["Practice to","تدرّب لإتقان","תרגלו כדי"],["master balancing.","الموازنة.","לשלוט באיזון."],["Choose a difficulty, practice with instant feedback, or take a quiz and see your results at the end.","اختر مستوى الصعوبة، وتدرّب مع ملاحظات فورية، أو أجرِ اختبارًا واطّلع على نتيجتك في النهاية.","בחרו רמת קושי, תרגלו עם משוב מיידי או ענו על חידון וצפו בתוצאות בסיום."],["DIFFICULTY","مستوى الصعوبة","רמת קושי"],["Choose a level","اختر مستوى","בחרו רמה"],["Simple equations and core ideas","معادلات بسيطة ومفاهيم أساسية","משוואות פשוטות ורעיונות בסיסיים"],["Parentheses and more steps","أقواس وخطوات أكثر","סוגריים ושלבים נוספים"],["Complex and combustion reactions","تفاعلات معقدة وتفاعلات احتراق","תגובות מורכבות ותגובות בעירה"],["EXPERIENCE","نمط التعلّم","אופן התרגול"],["Practice or Quiz?","تدريب أم اختبار؟","תרגול או חידון?"],["Practice — instant feedback","تدريب — ملاحظات فورية","תרגול — משוב מיידי"],["Quiz — final results","اختبار — النتيجة النهائية","חידון — תוצאות בסיום"],["QUESTION TYPE","نوع السؤال","סוג השאלה"],["How will you answer?","كيف ستجيب؟","איך תענו?"],["Multiple choice","اختيار من متعدد","בחירה מרובה"],["Type the coefficients","اكتب المعاملات","הקלידו את המקדמים"],["Start practice","ابدأ التدريب","התחילו לתרגל"],["Get feedback after every answer and learn from mistakes.","احصل على ملاحظات بعد كل إجابة وتعلّم من الأخطاء.","קבלו משוב אחרי כל תשובה ולמדו מהטעויות."],["Retry mistakes only","أعد محاولة الأخطاء فقط","תרגלו שוב רק את הטעויות"],["No completed sessions yet. Finish a practice or quiz session and it will appear here.","لا توجد جلسات مكتملة بعد. أنهِ جلسة تدريب أو اختبار وستظهر هنا.","עדיין אין מפגשים שהושלמו. השלימו תרגול או חידון והוא יופיע כאן."],["Solo Practice and Multiplayer Challenge are separate experiences. In a challenge, both players get the same questions and race against the clock.","التدريب الفردي والتحدي متعدد اللاعبين تجربتان منفصلتان. في التحدي، يحصل اللاعبان على الأسئلة نفسها ويتنافسان ضد الوقت.","תרגול אישי ואתגר מרובה משתתפים הם מצבים נפרדים. באתגר שני השחקנים מקבלים אותן שאלות ומתחרים נגד השעון."],["Same questions • 60-second challenge • live progress • final comparison","الأسئلة نفسها • تحدٍ لمدة 60 ثانية • تقدم مباشر • مقارنة نهائية","אותן שאלות • אתגר של 60 שניות • התקדמות בזמן אמת • השוואה סופית"],["Match with an available player.","العب ضد لاعب متاح.","התאימו את עצמכם לשחקן זמין."],["Create a private room and send the player your challenge code or link.","أنشئ غرفة خاصة وأرسل للاعب رمز التحدي أو الرابط.","צרו חדר פרטי ושלחו לשחקן את קוד האתגר או הקישור."],["Both players receive the identical question set.","يحصل اللاعبان على مجموعة الأسئلة نفسها.","שני השחקנים מקבלים אותה קבוצת שאלות בדיוק."],["Timer and progress update while you solve.","يُحدّث المؤقت والتقدم أثناء الحل.","הזמן וההתקדמות מתעדכנים בזמן הפתרון."],["Track your progress during the match.","تابع تقدمك أثناء المباراة.","עקבו אחר ההתקדמות במהלך המשחק."],["See both scores and who won after a real challenge.","شاهد نتيجتي اللاعبين والفائز بعد انتهاء التحدي.","ראו את הניקוד של שני השחקנים ומי ניצח לאחר האתגר."],["Choose “Invite a specific player”, create a private challenge, then send the generated challenge code or share link to that player. They can join from this page.","اختر «دعوة لاعب محدد»، وأنشئ تحديًا خاصًا، ثم أرسل للاعب رمز التحدي أو رابط المشاركة. يمكنه الانضمام من هذه الصفحة.","בחרו „הזמנת שחקן מסוים”, צרו אתגר פרטי ושלחו לשחקן את קוד האתגר או קישור השיתוף. הוא יוכל להצטרף מהעמוד הזה."],["Ranked by challenge solve time.","مرتّب حسب زمن حل التحدي.","הדירוג נקבע לפי זמן פתרון האתגר."],["Loading…","جارٍ التحميل…","בטעינה…"],["How inviting works","كيف تعمل الدعوة؟","איך פועלת ההזמנה?"],["Enter a chemical equation and get the balanced result immediately, with optional step-by-step and algebra explanations.","أدخل معادلة كيميائية واحصل فورًا على المعادلة الموزونة، مع إمكانية عرض شرح خطوة بخطوة وشرح جبري.","הזינו משוואה כימית וקבלו מיד את התוצאה המאוזנת, עם אפשרות להסברים שלב אחר שלב והסברים אלגבריים."],["The number of each element must be the same on both sides.","يجب أن يكون عدد ذرات كل عنصر متساويًا في الطرفين.","מספר האטומים של כל יסוד חייב להיות שווה בשני הצדדים."],["Use normal numbers for coefficients; use the subscript buttons for formula numbers.","استخدم الأرقام العادية للمعاملات، وأزرار الأرقام السفلية لأرقام الصيغ.","השתמשו במספרים רגילים למקדמים ובכפתורי המספרים התחתיים למספרים בנוסחאות."],["Enter a chemical equation and check whether it is balanced. The Checker compares the atom count of every element on both sides and explains any imbalance.","أدخل معادلة كيميائية للتحقق من توازنها. تقارن أداة التحقق عدد ذرات كل عنصر في الطرفين وتشرح أي اختلال.","הזינו משוואה כימית ובדקו אם היא מאוזנת. כלי הבדיקה משווה את מספר האטומים של כל יסוד בשני הצדדים ומסביר כל חוסר איזון."],["Choose an equation to place it in the checking box.","اختر معادلة لوضعها في مربع التحقق.","בחרו משוואה להצגתה בתיבת הבדיקה."],["Open the Balancer to calculate the correct coefficients, or use the learning guide.","افتح أداة الموازنة لحساب المعاملات الصحيحة، أو استخدم دليل التعلّم.","פתחו את כלי האיזון כדי לחשב את המקדמים הנכונים, או השתמשו במדריך הלמידה."],["Beginner Chemistry Lessons — Chemistry Equations","دروس الكيمياء للمبتدئين — معادلات الكيمياء","כימיה למתחילים — משוואות כימיות"],["Intermediate Chemistry Lessons — Chemistry Equations","دروس الكيمياء للمستوى المتوسط — معادلات الكيمياء","כימיה ברמת ביניים — משוואות כימיות"],["Advanced Chemistry Lessons — Chemistry Equations","دروس الكيمياء المتقدمة — معادلات الكيمياء","כימיה מתקדמת — משוואות כימיות"],["Challenges — Chemistry Equations","التحديات — معادلات الكيمياء","אתגרים — משוואות כימיות"],["Practice & Quiz — Chemistry Equations","التدريب والاختبار — معادلات الكيمياء","תרגול וחידון — משוואות כימיות"],["Chemistry Equations — Learn","معادلات الكيمياء — التعلّم","משוואות כימיות — למידה"],["Chemistry Equations — Balancer","معادلات الكيمياء — موازنة المعادلات","משוואות כימיות — איזון משוואות"],["Checker — Chemistry Equations","التحقق — معادلات الكيمياء","בדיקה — משוואות כימיות"],["01 · WHAT IS A CHEMICAL EQUATION?","01 · ما المعادلة الكيميائية؟","01 · מהי משוואה כימית?"],["02 · READING CHEMICAL FORMULAS","02 · قراءة الصيغ الكيميائية","02 · קריאת נוסחאות כימיות"],["03 · CONSERVATION OF MASS","03 · حفظ الكتلة","03 · שימור המסה"],["04 · HOW TO BALANCE A CHEMICAL EQUATION","04 · كيفية موازنة معادلة كيميائية","04 · איך מאזנים משוואה כימית?"],["Worked example","مثال محلول","דוגמה פתורה"],["Balance Fe + O₂ → Fe₂O₃.","وازن Fe + O₂ → Fe₂O₃.","אזנו Fe + O₂ → Fe₂O₃."],["Balance H₂ + Cl₂ → HCl.","وازن H₂ + Cl₂ → HCl.","אזנו H₂ + Cl₂ → HCl."],["Balance N₂ + H₂ → NH₃.","وازن N₂ + H₂ → NH₃.","אזנו N₂ + H₂ → NH₃."],["Balance H₂ + O₂ → H₂O.","وازن H₂ + O₂ → H₂O.","אזנו H₂ + O₂ → H₂O."],["Practice Beginner Quiz","اختبار تدريب المبتدئين","תרגול וחידון למתחילים"],["Practice Medium Quiz","اختبار تدريب المستوى المتوسط","תרגול וחידון לרמת ביניים"],["NaOH + HCl → NaCl + H₂O","NaOH + HCl → NaCl + H₂O","NaOH + HCl → NaCl + H₂O"],["Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄","Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄","Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄"],["Balance Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄.","وازن Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄.","אזנו Fe₂(SO₄)₃ + KOH → Fe(OH)₃ + K₂SO₄."],["Balance CH₄ + O₂ → CO₂ + H₂O.","وازن CH₄ + O₂ → CO₂ + H₂O.","אזנו CH₄ + O₂ → CO₂ + H₂O."],["Balance C₂H₅OH + O₂ → CO₂ + H₂O.","وازن C₂H₅OH + O₂ → CO₂ + H₂O.","אזנו C₂H₅OH + O₂ → CO₂ + H₂O."],["MnO₄⁻ + Fe²⁺ + H⁺ → Mn²⁺ + Fe³⁺ + H₂O","MnO₄⁻ + Fe²⁺ + H⁺ → Mn²⁺ + Fe³⁺ + H₂O","MnO₄⁻ + Fe²⁺ + H⁺ → Mn²⁺ + Fe³⁺ + H₂O"],["aFe + bO₂ → cFe₂O₃","aFe + bO₂ → cFe₂O₃","aFe + bO₂ → cFe₂O₃"],["Learn chemistry","تعلّم الكيمياء","למדו כימיה"],["Start with the basics","ابدأ بالأساسيات","התחילו מהיסודות"],["Already know the basics? Take a quiz","هل تعرف الأساسيات بالفعل؟ أجرِ اختبارًا","כבר מכירים את היסודות? ענו על חידון"],["Go straight to the balancer","انتقل مباشرةً إلى أداة الموازنة","עברו ישירות לכלי האיזון"],["Continue learning","تابع التعلّم","המשיכו ללמוד"],["Your current lesson will be saved so you can continue where you left off.","سيُحفظ درسك الحالي لتتمكن من المتابعة من حيث توقفت.","השיעור הנוכחי יישמר כדי שתוכלו להמשיך מהמקום שבו הפסקתם."],["⚡ DAILY CHALLENGE","⚡ تحدي اليوم","⚡ אתגר יומי"],["A new chemistry challenge every day","تحدٍ كيميائي جديد كل يوم","אתגר כימיה חדש בכל יום"],["Today's challenge","تحدي اليوم","האתגר של היום"],["Start Daily Challenge","ابدأ تحدي اليوم","התחילו את האתגר היומי"],["PRACTICE & TOOLS","التدريب والأدوات","תרגול וכלים"],["Put your knowledge to work","طبّق ما تعلمته","יישמו את הידע שלכם"],["Use these tools after a lesson—or whenever you want to test what you know.","استخدم هذه الأدوات بعد الدرس أو كلما أردت اختبار معرفتك.","השתמשו בכלים האלה אחרי שיעור או בכל פעם שתרצו לבדוק את הידע שלכם."],["CHECK YOUR UNDERSTANDING","تحقّق من فهمك","בדקו את ההבנה שלכם"],["Answer questions and see how well you understand the material.","أجب عن الأسئلة واكتشف مدى فهمك للمادة.","ענו על שאלות ובדקו עד כמה אתם מבינים את החומר."],["Take a quiz →","أجرِ اختبارًا ←","ענו על חידון ←"],["BUILD FLUENCY","طوّر مهارتك","שפרו את המיומנות"],["Work through balancing problems and practise at your own pace.","حلّ مسائل الموازنة وتدرّب بالوتيرة التي تناسبك.","פתרו תרגילי איזון ותרגלו בקצב שלכם."],["Explore challenges →","استكشف التحديات ←","גלו אתגרים ←"],["SOLVE AN EQUATION","حلّ معادلة","פתרו משוואה"],["Equation Balancer","أداة موازنة المعادلات","מאזן משוואות"],["Enter a chemical equation and check its balanced coefficients.","أدخل معادلة كيميائية وتحقق من معاملات الموازنة.","הזינו משוואה כימית ובדקו את מקדמי האיזון שלה."],["Open balancer →","افتح أداة الموازنة ←","פתחו את כלי האיזון ←"],["VERIFY YOUR WORK","تحقّق من عملك","בדקו את העבודה"],["Equation Checker","أداة التحقق من المعادلات","בודק משוואות"],["Check whether both sides contain the same number of atoms.","تحقّق مما إذا كان عدد الذرات متساويًا في الطرفين.","בדקו אם מספר האטומים שווה בשני הצדדים."],["Check an equation →","تحقّق من معادلة ←","בדקו משוואה ←"],["COMMON MISTAKES","أخطاء شائعة","טעויות נפוצות"],["What to watch for","ما الذي ينبغي الانتباه إليه","על מה חשוב להקפיד"],["Changing subscripts","تغيير الأرقام السفلية","שינוי מספרים תחתיים"],["Changing H₂O into H₂O₂ changes the substance. Use coefficients instead.","يؤدي تغيير H₂O إلى H₂O₂ إلى تغيير المادة. استخدم المعاملات بدلًا من ذلك.","שינוי H₂O ל-H₂O₂ משנה את החומר. השתמשו במקדמים במקום זאת."],["Forgetting diatomic forms","نسيان الصيغ ثنائية الذرة","שכחת צורות דו-אטומיות"],["Free oxygen is O₂, not O. The same rule applies to the other six diatomic elements.","الأكسجين الحر هو O₂ وليس O. وتنطبق القاعدة نفسها على العناصر الستة الأخرى ثنائية الذرة.","חמצן חופשי הוא O₂ ולא O. אותו כלל חל על ששת היסודות הדו-אטומיים האחרים."],["Balancing only one element","موازنة عنصر واحد فقط","איזון של יסוד אחד בלבד"],["Always recount every element after changing a coefficient.","أعد عدّ كل عنصر بعد تغيير أي معامل.","ספרו מחדש כל יסוד לאחר שינוי מקדם."],["Stopping before reduction","التوقف قبل الاختزال","עצירה לפני צמצום"],["A final equation should use the smallest whole-number coefficient ratio.","يجب أن تستخدم المعادلة النهائية أبسط نسبة صحيحة للمعاملات.","המשוואה הסופית צריכה להשתמש ביחס המקדמים השלם הקטן ביותר."],["03 · MULTIPLAYER","03 · اللعب الجماعي","03 · משחק מרובה משתתפים"],["⚡ LIVE CHALLENGE","⚡ تحدٍ مباشر","⚡ אתגר בזמן אמת"],["🌐 Random opponent","🌐 خصم عشوائي","🌐 יריב אקראי"],["🎯 Invite a specific player","🎯 دعوة لاعب محدد","🎯 הזמנת שחקן מסוים"],["🔑 Join with challenge code","🔑 الانضمام برمز التحدي","🔑 הצטרפות באמצעות קוד אתגר"],["🎯 Specific player","🎯 لاعب محدد","🎯 שחקן מסוים"],["⚡ Same questions","⚡ الأسئلة نفسها","⚡ אותן שאלות"],["⏱ Live competition","⏱ منافسة مباشرة","⏱ תחרות בזמן אמת"],["📊 Live score","📊 النتيجة المباشرة","📊 ניקוד בזמן אמת"],["🏆 Final comparison","🏆 المقارنة النهائية","🏆 השוואה סופית"],["🏆 LEADERBOARD","🏆 لوحة المتصدرين","🏆 טבלת מובילים"],["03 · BALANCER","03 · الموازنة","03 · איזון משוואות"],["Balance equations.","وازن المعادلات.","אזנו משוואות."],["Understand why.","افهم السبب.","הבינו מדוע."],["Conservation of atoms","حفظ الذرات","שימור האטומים"],["BALANCE","الموازنة","איזון"],["Balance an equation","وازن معادلة","אזנו משוואה"],["Equation editor","محرر المعادلات","עורך משוואות"],["Tap a symbol to insert it","اضغط على رمز لإدراجه","לחצו על סמל כדי להוסיף אותו"],["✎ Handwriting input","✎ الإدخال بالكتابة اليدوية","✎ קלט בכתב יד"],["04 · CHECKER","04 · التحقق","04 · בדיקה"],["Check your","تحقّق من","בדקו את"],["equation.","معادلتك.","המשוואה שלכם."],["✓ Same elements on both sides","✓ العناصر نفسها في الطرفين","✓ אותם יסודות בשני הצדדים"],["✓ Same number of atoms for every element","✓ العدد نفسه من الذرات لكل عنصر","✓ אותו מספר אטומים לכל יסוד"],["✓ Valid chemical formulas","✓ صيغ كيميائية صحيحة","✓ נוסחאות כימיות תקינות"],["✓ Simplest whole-number coefficients","✓ أبسط معاملات صحيحة","✓ המקדמים השלמים הפשוטים ביותר"],["Check equation balance","تحقّق من توازن المعادلة","בדקו את איזון המשוואה"],["← Balance an equation","← وازن معادلة","← אזנו משוואה"],["What is the balanced form of Fe + O₂ → Fe₂O₃?","ما الصيغة الموزونة للمعادلة Fe + O₂ → Fe₂O₃؟","מהי הצורה המאוזנת של Fe + O₂ → Fe₂O₃?"],["What is the balanced form of H₂ + Cl₂ → HCl?","ما الصيغة الموزونة للمعادلة H₂ + Cl₂ → HCl؟","מהי הצורה המאוזנת של H₂ + Cl₂ → HCl?"],["What is the balanced form of N₂ + H₂ → NH₃?","ما الصيغة الموزونة للمعادلة N₂ + H₂ → NH₃؟","מהי הצורה המאוזנת של N₂ + H₂ → NH₃?"],["What is the balanced form of H₂ + O₂ → H₂O?","ما الصيغة الموزونة للمعادلة H₂ + O₂ → H₂O؟","מהי הצורה המאוזנת של H₂ + O₂ → H₂O?"],["What should you check before balancing?","ما الذي ينبغي التحقق منه قبل الموازنة؟","מה צריך לבדוק לפני האיזון?"],["What should you use to change atom counts?","ما الذي ينبغي استخدامه لتغيير أعداد الذرات؟","במה צריך להשתמש כדי לשנות את מספר האטומים?"],["What should you do after changing coefficients?","ماذا ينبغي أن تفعل بعد تغيير المعاملات؟","מה צריך לעשות אחרי שינוי המקדמים?"],["What is the balanced form of CH₄ + O₂ → CO₂ + H₂O?","ما الصيغة الموزونة للمعادلة CH₄ + O₂ → CO₂ + H₂O؟","מהי הצורה המאוזנת של CH₄ + O₂ → CO₂ + H₂O?"],["Which element is usually balanced first in a hydrocarbon combustion reaction?","أي عنصر يُوازن عادةً أولًا في تفاعل احتراق هيدروكربوني؟","איזה יסוד מאזנים בדרך כלל ראשון בתגובת בעירת פחמימן?"],["Why is oxygen usually left until last?","لماذا يُترك الأكسجين عادةً إلى النهاية؟","למה בדרך כלל משאירים את החמצן לסוף?"],["Which species is oxidized in Zn + Cu²⁺ → Zn²⁺ + Cu?","أي نوع كيميائي يتأكسد في Zn + Cu²⁺ → Zn²⁺ + Cu؟","איזה מין כימי מתחמצן ב-Zn + Cu²⁺ → Zn²⁺ + Cu?"],["Which species is reduced in Zn + Cu²⁺ → Zn²⁺ + Cu?","أي نوع كيميائي يُختزل في Zn + Cu²⁺ → Zn²⁺ + Cu؟","איזה מין כימי מחוזר ב-Zn + Cu²⁺ → Zn²⁺ + Cu?"],["Why must charge be checked in an ionic equation?","لماذا يجب التحقق من الشحنة في المعادلة الأيونية؟","למה צריך לבדוק מטען במשוואה יונית?"],["Why must charge be conserved?","لماذا يجب حفظ الشحنة؟","למה חייבים לשמר מטען?"],["What is used to balance oxygen in acidic solution?","ما الذي يُستخدم لموازنة الأكسجين في محلول حمضي؟","במה משתמשים לאיזון חמצן בתמיסה חומצית?"],["What is used to balance charge in the half-reaction method?","ما الذي يُستخدم لموازنة الشحنة في طريقة أنصاف التفاعلات؟","במה משתמשים לאיזון המטען בשיטת חצאי התגובות?"],["What do you assign to each formula in an algebraic balancing method?","ماذا تُعيّن لكل صيغة في طريقة الموازنة الجبرية؟","מה מציבים לכל נוסחה בשיטת איזון אלגברית?"],["Why must the final coefficients be positive?","لماذا يجب أن تكون المعاملات النهائية موجبة؟","למה המקדמים הסופיים חייבים להיות חיוביים?"],["Why should the final ratio be reduced to the smallest whole numbers?","لماذا ينبغي اختزال النسبة النهائية إلى أصغر أعداد صحيحة؟","למה צריך לצמצם את היחס הסופי למספרים השלמים הקטנים ביותר?"],["No — oxygen has 2 on the left and 1 on the right.","لا — يوجد 2 أكسجين في الطرف الأيسر و1 في الطرف الأيمن.","לא — בצד שמאל יש 2 חמצן ובצד ימין 1."],["No — hydrogen has 1 on the left and 2 on the right.","لا — يوجد 1 هيدروجين في الطرف الأيسر و2 في الطرف الأيمن.","לא — בצד שמאל יש 1 מימן ובצד ימין 2."],["The balanced equation is:","المعادلة الموزونة هي:","המשוואה המאוזנת היא:"],["Select a difficulty","اختر مستوى الصعوبة","בחרו רמת קושי"],["Time limit","الحد الزمني","מגבלת זמן"],["5 minutes","5 دقائق","5 דקות"],["7 minutes","7 دقائق","7 דקות"],["10 minutes","10 دقائق","10 דקות"],["Time remaining","الوقت المتبقي","הזמן שנותר"],["Answer each question. Your results appear when you finish.","أجب عن كل سؤال. ستظهر نتيجتك عند الانتهاء.","ענו על כל שאלה. התוצאות יופיעו בסיום."],["Get feedback after each answer and learn from mistakes.","احصل على ملاحظات بعد كل إجابة وتعلّم من الأخطاء.","קבלו משוב אחרי כל תשובה ולמדו מהטעויות."],["CONCEPT MASTERY","إتقان المفاهيم","שליטה במושגים"],["Skills","المهارات","מיומנויות"],["Based on answered questions","بناءً على الأسئلة المجاب عنها","מבוסס על שאלות שנענו"],["Not tested","لم يُختبر","לא נבדק"],["Strong","متقن","חזק"],["Needs practice","يحتاج إلى تدريب","דורש תרגול"],["Weak","ضعيف","חלש"],["Counting atoms","عدّ الذرات","ספירת אטומים"],["Coefficients","المعاملات","מקדמים"],["Diatomic elements","العناصر ثنائية الذرة","יסודות דו-אטומיים"],["Parentheses","الأقواس","סוגריים"],["Polyatomic ions","الأيونات متعددة الذرات","יונים רב-אטומיים"],["Combustion","الاحتراق","בעירה"],["Redox","الأكسدة والاختزال","חמצון-חיזור"],["Ionic equations","المعادلات الأيونية","משוואות יוניות"],["Tricky formulas","الصيغ التي تحتاج إلى انتباه","נוסחאות מורכבות"],["Already-balanced equations","معادلات موزونة مسبقًا","משוואות שכבר מאוזנות"],["questions","أسئلة","שאלות"],["concepts","مفاهيم","מושגים"],["Daily practice streak is unavailable right now.","سلسلة التدريب اليومية غير متاحة حاليًا.","רצף התרגול היומי אינו זמין כרגע."],["Calculated from daily challenges completed on this browser/device.","يُحسب استنادًا إلى التحديات اليومية المكتملة على هذا المتصفح/الجهاز.","מחושב לפי אתגרים יומיים שהושלמו בדפדפן/במכשיר הזה."],["Set a new password","تعيين كلمة مرور جديدة","הגדרת סיסמה חדשה"],["This is for an existing account that currently has no password. Your account and saved scores are preserved.","هذا لحساب موجود لا يحتوي حاليًا على كلمة مرور. سيظل حسابك ونتائجك المحفوظة كما هي.","האפשרות מיועדת לחשבון קיים שעדיין אין לו סיסמה. החשבון והתוצאות השמורות יישמרו."],["Username","اسم المستخدم","שם משתמש"],["New password","كلمة مرور جديدة","סיסמה חדשה"],["Confirm new password","تأكيد كلمة المرور الجديدة","אימות הסיסמה החדשה"],["Set password","تعيين كلمة المرور","הגדרת סיסמה"],["Could not set the password.","تعذّر تعيين كلمة المرور.","לא ניתן להגדיר את הסיסמה."],["Password set successfully. Redirecting to your profile…","تم تعيين كلمة المرور بنجاح. جارٍ الانتقال إلى ملفك الشخصي…","הסיסמה הוגדרה בהצלחה. מעבירים לפרופיל שלך…"],["Set Password — Chemistry Equations","تعيين كلمة المرور — معادلات الكيمياء","הגדרת סיסמה — משוואות כימיות"],["Keep me signed in on this device","أبقني مسجّل الدخول على هذا الجهاز","השאירו אותי מחובר במכשיר הזה"],["Sign in to access your saved scores and progress.","سجّل الدخول للوصول إلى نتائجك وتقدمك المحفوظين.","התחברו כדי לגשת לתוצאות ולהתקדמות השמורות שלכם."],["Could not connect to the account server.","تعذّر الاتصال بخادم الحسابات.","לא ניתן להתחבר לשרת החשבונות."],["Could not complete the request.","تعذّر إكمال الطلب.","לא ניתן להשלים את הבקשה."],["Could not sign out from all devices.","تعذّر تسجيل الخروج من جميع الأجهزة.","לא ניתן להתנתק מכל המכשירים."],["Recovery code is required.","رمز الاسترداد مطلوب.","נדרש קוד שחזור."],["New password is required.","كلمة المرور الجديدة مطلوبة.","נדרשת סיסמה חדשה."],["The server did not return a recovery code.","لم يُرجع الخادم رمز استرداد.","השרת לא החזיר קוד שחזור."],["Could not generate a recovery code.","تعذّر إنشاء رمز الاسترداد.","לא ניתן ליצור קוד שחזור."],["Current password is required.","كلمة المرور الحالية مطلوبة.","נדרשת הסיסמה הנוכחית."],["Changing password…","جارٍ تغيير كلمة المرور…","משנים סיסמה…"],["Password changed successfully.","تم تغيير كلمة المرور بنجاح.","הסיסמה שונתה בהצלחה."],["Could not change the password.","تعذّر تغيير كلمة المرور.","לא ניתן לשנות את הסיסמה."],["Delete your account and saved account data? This cannot be undone.","هل تريد حذف حسابك وبياناته المحفوظة؟ لا يمكن التراجع عن ذلك.","למחוק את החשבון ואת הנתונים השמורים? אי אפשר לבטל פעולה זו."],["Enter your password to confirm account deletion:","أدخل كلمة المرور لتأكيد حذف الحساب:","הזינו את הסיסמה כדי לאשר את מחיקת החשבון:"],["Deleting account…","جارٍ حذف الحساب…","מוחקים את החשבון…"],["Could not delete the account.","تعذّر حذف الحساب.","לא ניתן למחוק את החשבון."],["You are signed in.","أنت مسجّل الدخول.","אתם מחוברים."],["Account info","معلومات الحساب","פרטי חשבון"],["Admin tools","أدوات الإدارة","כלי ניהול"],["Generate recovery code","إنشاء رمز استرداد","יצירת קוד שחזור"],["Sign out from all devices","تسجيل الخروج من جميع الأجهزة","התנתקות מכל המכשירים"],["Account Recovery Code","رمز استرداد الحساب","קוד שחזור חשבון"],["Keep this code private and safe.","احتفظ بهذا الرمز سرّيًا وفي مكان آمن.","שמרו על הקוד הזה בסוד ובמקום בטוח."],["Password must be at least 8 characters.","يجب أن تتكون كلمة المرور من 8 أحرف على الأقل.","הסיסמה חייבת להכיל לפחות 8 תווים."],["Please confirm your password.","يرجى تأكيد كلمة المرور.","אשרו את הסיסמה."],["Passwords do not match.","كلمتا المرور غير متطابقتين.","הסיסמאות אינן תואמות."],["Name is required.","الاسم مطلوب.","נדרש שם."],["Password is required.","كلمة المرور مطلوبة.","נדרשת סיסמה."],["Please allow pop-ups to print the recovery code.","يرجى السماح بالنوافذ المنبثقة لطباعة رمز الاسترداد.","אפשרו חלונות קופצים כדי להדפיס את קוד השחזור."],["Could not copy the code. Please copy it manually.","تعذّر نسخ الرمز. يرجى نسخه يدويًا.","לא ניתן להעתיק את הקוד. העתיקו אותו ידנית."],["Copy code","نسخ الرمز","העתקת הקוד"],["I’ve saved it","لقد حفظته","שמרתי אותו"],["Recovery code saved. You are signed in.","تم حفظ رمز الاسترداد. أنت مسجّل الدخول.","קוד השחזור נשמר. אתם מחוברים."],["View profile","عرض الملف الشخصي","הצגת הפרופיל"],["Change password","تغيير كلمة المرور","שינוי סיסמה"],["Account & security","الحساب والأمان","חשבון ואבטחה"],["Manage your session and password securely.","أدر جلستك وكلمة المرور بأمان.","נהלו את ההתחברות והסיסמה בצורה מאובטחת."],["Create an account","إنشاء حساب","יצירת חשבון"],["Create an account to keep your learning progress associated with your username.","أنشئ حسابًا لربط تقدمك في التعلّم باسم المستخدم الخاص بك.","צרו חשבון כדי לשייך את התקדמות הלמידה לשם המשתמש שלכם."],["Already have an account?","هل لديك حساب بالفعل؟","כבר יש לכם חשבון?"],["Forgot password?","هل نسيت كلمة المرور؟","שכחתם סיסמה?"],["Remember your password?","هل تتذكر كلمة المرور؟","זוכרים את הסיסמה?"],["New here?","جديد هنا؟","חדשים כאן?"],["Reset password","إعادة تعيين كلمة المرور","איפוס סיסמה"],["Enter the recovery code you saved when creating your account or generating a new code in Account & security.","أدخل رمز الاسترداد الذي حفظته عند إنشاء الحساب أو إنشاء رمز جديد في «الحساب والأمان».","הזינו את קוד השחזור ששמרתם בעת יצירת החשבון או בעת יצירת קוד חדש ב״חשבון ואבטחה״."],["Sign out","تسجيل الخروج","התנתקות"],["Setting password…","جارٍ تعيين كلمة المرور…","מגדירים סיסמה…"],["🌙 Dark","🌙 داكن","🌙 כהה"],["Toggle dark mode","تبديل الوضع الداكن","החלפת מצב כהה"],["Quick atom-count reference","مرجع سريع لعدّ الذرات","עזר מהיר לספירת אטומים"],["✓ Balanced","✓ موزونة","✓ מאוזנת"],["step by step.","خطوة بخطوة.","שלב אחר שלב."],["⚗ Chemistry Equations","⚗ معادلات الكيمياء","⚗ משוואות כימיות"],["01 · LEARNING GUIDE","01 · دليل التعلّم","01 · מדריך למידה"],["Learn chemical equations, conservation of mass, coefficients, diatomic elements, and the complete balancing method.","تعلّم المعادلات الكيميائية وحفظ الكتلة والمعاملات والعناصر ثنائية الذرة وطريقة الموازنة الكاملة.","למדו משוואות כימיות, שימור מסה, מקדמים, יסודות דו-אטומיים ואת שיטת האיזון המלאה."],["Learn polyatomic ions, parentheses, fractional coefficients, and more complicated balancing problems.","تعلّم الأيونات متعددة الذرات والأقواس والمعاملات الكسرية ومسائل الموازنة الأكثر تعقيدًا.","למדו יונים רב-אטומיים, סוגריים, מקדמים שבריים ובעיות איזון מורכבות יותר."],["Learn combustion, redox, complex ionic equations, and systematic balancing.","تعلّم الاحتراق والأكسدة والاختزال والمعادلات الأيونية المعقدة والموازنة المنهجية.","למדו בעירה, חמצון-חיזור, משוואות יוניות מורכבות ואיזון שיטתי."],["02 · PRACTICE & QUIZ","02 · التدريب والاختبار","02 · תרגול וחידון"],["🟢 Beginner","🟢 مبتدئ","🟢 מתחילים"],["🟡 Intermediate","🟡 متوسط","🟡 ביניים"],["🔴 Advanced","🔴 متقدم","🔴 מתקדם"],["BEGINNER","مبتدئ","מתחילים"],["Profile — Chemistry Equations","الملف الشخصي — معادلات الكيمياء","פרופיל — משוואות כימיות"],["Chemistry","الكيمياء","כימיה"],["🏆 Certificate Preview","🏆 معاينة الشهادة","🏆 תצוגה מקדימה של התעודה"],["Beginner","مبتدئ","מתחילים"],["Intermediate","متوسط","ביניים"],["Advanced","متقدم","מתקדם"],["What is a chemical equation?","ما المعادلة الكيميائية؟","מהי משוואה כימית?"],["Reading chemical formulas","قراءة الصيغ الكيميائية","קריאת נוסחאות כימיות"],["Conservation of mass","حفظ الكتلة","שימור המסה"],["How to balance a chemical equation","كيفية موازنة معادلة كيميائية","איך מאזנים משוואה כימית?"],["Putting it all together","جمع المفاهيم معًا","שילוב כל החומר"],["Fractional coefficients","المعاملات الكسرية","מקדמים שבריים"],["Complicated reactions","تفاعلات معقدة","תגובות מורכבות"],["Complex ionic equations","معادلات أيونية معقدة","משוואות יוניות מורכבות"],["Systematic balancing","الموازنة المنهجية","איזון שיטתי"],["Before starting Intermediate, check the five basics below.","قبل البدء بالمستوى المتوسط، تحقّق من الأساسيات الخمسة أدناه.","לפני תחילת רמת הביניים, בדקו את חמשת היסודות שלהלן."],["Before starting Advanced, check the five Intermediate concepts below.","قبل البدء بالمستوى المتقدم، تحقّق من مفاهيم المستوى المتوسط الخمسة أدناه.","לפני תחילת הרמה המתקדמת, בדקו את חמשת המושגים של רמת הביניים שלהלן."],["A detailed beginner path for understanding chemical equations and learning how to balance them.","مسار مفصّل للمبتدئين لفهم المعادلات الكيميائية وتعلّم موازنتها.","מסלול מפורט למתחילים להבנת משוואות כימיות וללימוד איזונן."],["Describe what happens in a reaction","صف ما يحدث في التفاعل","תארו מה מתרחש בתגובה"],["The equation tells us which substances participate in the reaction, but it is not balanced yet. A balanced equation must contain the same number of atoms of every element on both sides.","توضح المعادلة المواد المشاركة في التفاعل، لكنها لم تُوازن بعد. يجب أن تحتوي المعادلة الموزونة على العدد نفسه من ذرات كل عنصر في الطرفين.","המשוואה מציגה אילו חומרים משתתפים בתגובה, אך היא עדיין אינה מאוזנת. במשוואה מאוזנת חייב להיות אותו מספר אטומים מכל יסוד בשני הצדדים."],["Read from left to right: reactants → products. The plus sign separates substances on the same side, while the arrow separates reactants from products.","اقرأ من اليسار إلى اليمين: المتفاعلات ← النواتج. تفصل علامة الجمع بين المواد في الطرف نفسه، بينما يفصل السهم المتفاعلات عن النواتج.","קראו משמאל לימין: מגיבים → תוצרים. סימן הפלוס מפריד בין חומרים באותו צד, והחץ מפריד בין המגיבים לתוצרים."],["A chemical formula tells you which elements are present and how many atoms of each element are in one particle of the substance. A small number written after an element is a subscript.","توضح الصيغة الكيميائية العناصر الموجودة وعدد ذرات كل عنصر في جسيم واحد من المادة. يُسمّى الرقم الصغير المكتوب بعد رمز العنصر رقمًا سفليًا.","נוסחה כימית מציינת אילו יסודות קיימים וכמה אטומים מכל יסוד יש בחלקיק אחד של החומר. מספר קטן אחרי סמל יסוד נקרא מספר תחתי."],["H₂O contains 2 hydrogen atoms and 1 oxygen atom. When there is no subscript, the number is 1.","يحتوي H₂O على ذرتَي هيدروجين وذرة أكسجين واحدة. إذا لم يظهر رقم سفلي، فالعدد هو 1.","ב-H₂O יש שני אטומי מימן ואטום חמצן אחד. כשאין מספר תחתי, המספר הוא 1."],["In Ca(OH)₂, the subscript 2 applies to the entire OH group, so the formula contains 1 Ca, 2 O and 2 H.","في Ca(OH)₂، ينطبق الرقم السفلي 2 على مجموعة OH كلها، لذلك تحتوي الصيغة على ذرة Ca وذرتَي O وذرتَي H.","ב-Ca(OH)₂ המספר התחתי 2 חל על כל קבוצת OH, ולכן הנוסחה מכילה אטום Ca אחד, שני אטומי O ושני אטומי H."],["A coefficient is placed in front of a formula and multiplies the whole formula. A subscript is part of the formula. Never change a subscript while balancing because that changes the substance.","يوضع المعامل قبل الصيغة ويضرب الصيغة كلها، أما الرقم السفلي فهو جزء من الصيغة. لا تغيّر الرقم السفلي أثناء الموازنة لأن ذلك يغيّر المادة نفسها.","מקדם נכתב לפני נוסחה ומכפיל את כולה. מספר תחתי הוא חלק מהנוסחה. אין לשנות מספר תחתי בזמן איזון, משום שהדבר משנה את החומר."],["Atoms are rearranged, not created or destroyed","تُعاد ترتيبات الذرات ولا تُخلق أو تُدمّر","האטומים מסתדרים מחדש, אינם נוצרים ואינם נהרסים"],["In an ordinary chemical reaction, atoms are rearranged into new combinations. Therefore, every element must have the same total number of atoms before and after the reaction.","في التفاعل الكيميائي العادي، تُعاد ترتيبات الذرات في مجموعات جديدة. لذلك يجب أن يبقى العدد الإجمالي لذرات كل عنصر متساويًا قبل التفاعل وبعده.","בתגובה כימית רגילה האטומים מסתדרים בצירופים חדשים. לכן המספר הכולל של אטומי כל יסוד חייב להיות זהה לפני התגובה ואחריה."],["INTERMEDIATE · MEDIUM","متوسط · متوسط","ביניים · בינוני"],["ADVANCED · HARD","متقدم · صعب","מתקדם · קשה"],["Master difficult","أتقنوا","שלטו ב"],["reactions.","التفاعلات الصعبة.","תגובות קשות."],["Learn systematic methods for combustion, redox and complex ionic equations before testing yourself.","تعلّم طرقًا منهجية لموازنة الاحتراق والأكسدة والاختزال والمعادلات الأيونية المعقدة قبل اختبار نفسك.","למדו שיטות שיטתיות לאיזון בעירה, חמצון-חיזור ומשוואות יוניות מורכבות לפני שתבחנו את עצמכם."],["Balance C and H before O","وازن C وH قبل O","אזנו C ו-H לפני O"],["For hydrocarbons reacting with oxygen, carbon is usually easiest to balance first, then hydrogen, and oxygen last. If oxygen becomes odd, a temporary fraction can simplify the calculation.","عند تفاعل الهيدروكربونات مع الأكسجين، يكون من الأسهل عادةً موازنة الكربون أولًا ثم الهيدروجين وأخيرًا الأكسجين. إذا أصبح عدد ذرات الأكسجين فرديًا، فقد يسهّل كسر مؤقت الحساب.","בתגובת פחמימנים עם חמצן, בדרך כלל קל ביותר לאזן תחילה פחמן, אחר כך מימן ולבסוף חמצן. אם מספר אטומי החמצן אי-זוגי, שבר זמני עשוי לפשט את החישוב."],["Balance carbon: 3CO₂. Balance hydrogen: 4H₂O. The products contain 10 oxygen atoms, so use 5O₂.","وازن الكربون: 3CO₂. وازن الهيدروجين: 4H₂O. تحتوي النواتج على 10 ذرات أكسجين، لذا استخدم 5O₂.","מאזנים פחמן: 3CO₂. מאזנים מימן: 4H₂O. בתוצרים יש 10 אטומי חמצן, ולכן משתמשים ב-5O₂."],["Track atoms and electron transfer","تابع الذرات وانتقال الإلكترونات","עקבו אחר האטומים ומעבר האלקטרונים"],["Redox reactions involve oxidation and reduction. In addition to conserving atoms, ionic equations must conserve charge. Oxidation states can help identify which species are oxidized and reduced.","تشمل تفاعلات الأكسدة والاختزال عمليتَي الأكسدة والاختزال. إضافةً إلى حفظ الذرات، يجب أن تحفظ المعادلات الأيونية الشحنة أيضًا. تساعد أعداد التأكسد في تحديد الأنواع التي تتأكسد وتُختزل.","תגובות חמצון-חיזור כוללות חמצון וחיזור. בנוסף לשימור האטומים, משוואות יוניות חייבות לשמר גם את המטען. דרגות חמצון מסייעות לזהות אילו מינים מתחמצנים ואילו מתחזרים."],["Zinc loses two electrons and copper ions gain two. Atoms and total charge are both conserved.","يفقد الزنك إلكترونين وتكتسب أيونات النحاس إلكترونين. ويُحفظ كلٌّ من الذرات والشحنة الكلية.","אבץ מאבד שני אלקטרונים ויוני נחושת קולטים שניים. גם האטומים וגם המטען הכולל נשמרים."],["Balance atoms and charge","وازن الذرات والشحنة","אזנו אטומים ומטען"],["For ionic equations, conserving atoms is not enough: the total charge on both sides must also match. In acidic solution, H₂O and H⁺ can be used to balance oxygen and hydrogen; electrons are used to balance charge in half-reaction methods.","في المعادلات الأيونية لا يكفي حفظ الذرات؛ بل يجب أن تتساوى الشحنة الكلية في الطرفين أيضًا. في المحلول الحمضي، يمكن استخدام H₂O وH⁺ لموازنة الأكسجين والهيدروجين، وتُستخدم الإلكترونات لموازنة الشحنة في طريقة أنصاف التفاعلات.","במשוואות יוניות לא מספיק לשמר אטומים; גם המטען הכולל בשני הצדדים חייב להיות שווה. בתמיסה חומצית אפשר להשתמש ב-H₂O וב-H⁺ לאיזון חמצן ומימן, ובאלקטרונים לאיזון המטען בשיטת חצאי התגובות."],["Use half-reactions systematically rather than guessing coefficients. Balance elements other than H and O first, then O with water, H with H⁺, and charge with electrons.","השתמש بأنصاف التفاعلات بطريقة منهجية بدل تخمين المعاملات. وازن العناصر غير H وO أولًا، ثم O باستخدام الماء، وH باستخدام H⁺، والشحنة باستخدام الإلكترونات.","השתמשו בחצאי תגובות באופן שיטתי במקום לנחש מקדמים. אזנו תחילה יסודות מלבד H ו-O, אחר כך O בעזרת מים, H בעזרת H⁺, ואת המטען בעזרת אלקטרונים."],["Use algebra when guessing becomes difficult","استخدم الجبر عندما تصبح التخمينات صعبة","השתמשו באלגברה כשהניחוש נעשה קשה"],["Assign an unknown coefficient to every formula, write one conservation equation for each element, and solve the resulting system. Finally, scale the solution to the smallest positive whole-number coefficients.","عيّن معاملًا مجهولًا لكل صيغة، واكتب معادلة حفظ لكل عنصر، ثم حل النظام الناتج. أخيرًا، حوّل الحل إلى أصغر معاملات صحيحة موجبة.","הקצו מקדם לא ידוע לכל נוסחה, כתבו משוואת שימור לכל יסוד ופתרו את המערכת המתקבלת. לבסוף, התאימו את הפתרון למקדמים שלמים וחיוביים קטנים ככל האפשר."],["Iron gives a = 2c. Oxygen gives 2b = 3c. Choosing c = 2 produces a = 4 and b = 3.","يعطي الحديد a = 2c، ويعطي الأكسجين 2b = 3c. عند اختيار c = 2 نحصل على a = 4 وb = 3.","מהברזל מתקבל a = 2c. מהחמצן מתקבל 2b = 3c. בחירה ב-c = 2 נותנת a = 4 ו-b = 3."],["Turn equation balancing into a mini chemistry course: learn the idea, see it worked, then practise it before moving on.","حوّل موازنة المعادلات إلى دورة كيمياء مصغّرة: تعلّم الفكرة، وشاهد مثالًا محلولًا، ثم تدرّب قبل الانتقال إلى الدرس التالي.","הפכו את איזון המשוואות לקורס כימיה קצר: למדו את הרעיון, ראו פתרון מודגם ואז תרגלו לפני המעבר לשיעור הבא."],["Daily practice streak: 0 days","سلسلة التدريب اليومية: 0 أيام","רצף התרגול היומי: 0 ימים"],["Quiz history","سجل الاختبارات","היסטוריית החידונים"],["Best results and accuracy are stored locally.","تُحفظ أفضل النتائج والدقة على هذا الجهاز.","התוצאות הטובות ביותר והדיוק נשמרים מקומית במכשיר הזה."],["What gets checked?","ما الذي يتم التحقق منه؟","מה נבדק?"],["Try an example","جرّب مثالًا","נסו דוגמה"],["Need help?","تحتاج إلى مساعدة؟","צריכים עזרה?"],["Learn how →","تعلّم الطريقة ←","למדו איך ←"],["Draw a chemical equation, tap Recognize, check the transcription, then balance it.","ارسم معادلة كيميائية، واضغط «تعرّف»، وتحقق من النص المستخرج، ثم وازنها.","ציירו משוואה כימית, לחצו על «זיהוי», בדקו את התמלול ואז אזנו אותה."],["Draw an equation, then tap Recognize.","ارسم معادلة ثم اضغط «تعرّف».","ציירו משוואה ואז לחצו על «זיהוי»."],["Tap Select, then drag around the handwriting.","اضغط «تحديد»، ثم اسحب حول الكتابة اليدوية.","לחצו על «בחירה» ואז גררו סביב הכתב."],["Correct the recognized equation before balancing:","صحّح المعادلة التي تم التعرّف عليها قبل الموازنة:","תקנו את המשוואה שזוהתה לפני האיזון:"],["Balance corrected equation","وازن المعادلة المصححة","אזנו את המשוואה המתוקנת"],["Undo","تراجع","ביטול"],["Redo","إعادة","ביצוע מחדש"],["Eraser","ممحاة","מחק"],["Recognize","تعرّف","זיהוי"],["Select","تحديد","בחירה"],["Copy selection","نسخ التحديد","העתקת הבחירה"],["Paste selection","لصق التحديد","הדבקת הבחירה"],["ACCOUNT","الحساب","חשבון"],["Your profile","ملفك الشخصي","הפרופיל שלך"],["Loading profile…","جارٍ تحميل الملف الشخصي…","טוענים את הפרופיל…"],["Practice","تدرّب","תרגול"],["Sign in to access your saved scores and progress.","سجّل الدخول للوصول إلى نتائجك وتقدّمك المحفوظين.","התחברו כדי לגשת לתוצאות ולהתקדמות השמורות שלכם."],["Sign in","تسجيل الدخول","התחברות"],["Create account","إنشاء حساب","יצירת חשבון"],["Create your account","أنشئ حسابك","יצירת החשבון שלך"],["Name","الاسم","שם"],["Username","اسم المستخدم","שם משתמש"],["Password","كلمة المرور","סיסמה"],["Confirm password","تأكيد كلمة المرور","אימות סיסמה"],["Remember me","تذكرني","זכור אותי"],["Forgot password?","هل نسيت كلمة المرور؟","שכחתם סיסמה?"],["Reset password","إعادة تعيين كلمة المرور","איפוס סיסמה"],["Enter the recovery code you saved when creating your account or generating a new code in Account & security.","أدخل رمز الاسترداد الذي حفظته عند إنشاء الحساب أو إنشاء رمز جديد في «الحساب والأمان».","הזינו את קוד השחזור ששמרתם בעת יצירת החשבון או בעת יצירת קוד חדש ב״חשבון ואבטחה״."],["Sign out","تسجيل الخروج","התנתקות"],["Show","إظهار","הצגה"],["Hide","إخفاء","הסתרה"],["Save your recovery code","احفظ رمز الاسترداد","שמרו את קוד השחזור"],["This code can be used to reset your password if you forget it. Save it somewhere safe. It will not be shown again unless you generate a new one.","يمكن استخدام هذا الرمز لإعادة تعيين كلمة المرور إذا نسيتها. احفظه في مكان آمن؛ لن يظهر مجددًا إلا إذا أنشأت رمزًا جديدًا.","אפשר להשתמש בקוד הזה לאיפוס הסיסמה אם תשכחו אותה. שמרו אותו במקום בטוח; הוא לא יוצג שוב אלא אם תיצרו קוד חדש."],["Copy code","نسخ الرمز","העתקת הקוד"],["Print","طباعة","הדפסה"],["I've saved it","حفظته","שמרתי אותו"],["Copied!","تم النسخ!","הועתק!"],["Could not copy the code. Please copy it manually.","تعذّر نسخ الرمز. يُرجى نسخه يدويًا.","לא ניתן להעתיק את הקוד. העתיקו אותו ידנית."],["Please allow pop-ups to print the recovery code.","يرجى السماح بالنوافذ المنبثقة لطباعة رمز الاسترداد.","אפשרו חלונות קופצים כדי להדפיס את קוד השחזור."],["Name is required.","الاسم مطلوب.","נדרש שם."],["Username is required.","اسم المستخدم مطلوب.","נדרש שם משתמש."],["Password is required.","كلمة المرور مطلوبة.","נדרשת סיסמה."],["Password must be at least 8 characters.","يجب أن تتكون كلمة المرور من 8 أحرف على الأقل.","הסיסמה חייבת להכיל 8 תווים לפחות."],["Please confirm your password.","يرجى تأكيد كلمة المرور.","נא לאשר את הסיסמה."],["Passwords do not match.","كلمتا المرور غير متطابقتين.","הסיסמאות אינן תואמות."],["Creating account…","جارٍ إنشاء الحساب…","יוצרים חשבון…"],["Account created successfully.","تم إنشاء الحساب بنجاح.","החשבון נוצר בהצלחה."],["Could not connect to the account server.","تعذّر الاتصال بخادم الحساب.","לא ניתן להתחבר לשרת החשבון."],["Could not complete the request.","تعذّر إكمال الطلب.","לא ניתן להשלים את הבקשה."],["Could not set the password.","تعذّر تعيين كلمة المرور.","לא ניתן להגדיר את הסיסמה."],["Password set successfully. Redirecting to your profile…","تم تعيين كلمة المرور بنجاح. جارٍ الانتقال إلى ملفك الشخصي…","הסיסמה הוגדרה בהצלחה. עוברים לפרופיל…"],["Setting password…","جارٍ تعيين كلمة المرور…","מגדירים סיסמה…"],["Account","الحساب","חשבון"],["Sign out from all devices","تسجيل الخروج من جميع الأجهزة","התנתקות מכל המכשירים"],["Account & security","الحساب والأمان","חשבון ואבטחה"],["Generate recovery code","إنشاء رمز استرداد","יצירת קוד שחזור"],["Update password","تحديث كلمة المرور","עדכון סיסמה"],["Current password","كلمة المرور الحالية","הסיסמה הנוכחית"],["New password","كلمة المرور الجديدة","סיסמה חדשה"],["Confirm new password","تأكيد كلمة المرور الجديدة","אימות הסיסמה החדשה"],["Save changes","حفظ التغييرات","שמירת שינויים"],["Your account details are saved.","تم حفظ تفاصيل حسابك.","פרטי החשבון נשמרו."],["Could not sign out from all devices.","تعذّر تسجيل الخروج من جميع الأجهزة.","לא ניתן להתנתק מכל המכשירים."],["This username is already in use.","اسم المستخدم مستخدم بالفعل.","שם המשתמש כבר בשימוש."],["Invalid username or password.","اسم المستخدم أو كلمة المرور غير صحيحة.","שם המשתמש או הסיסמה שגויים."],["Please enter your username and password.","يرجى إدخال اسم المستخدم وكلمة المرور.","הזינו שם משתמש וסיסמה."],["Account settings","إعدادات الحساب","הגדרות חשבון"],["Daily practice streak is unavailable right now.","سلسلة التدريب اليومي غير متاحة حاليًا.","רצף התרגול היومي אינו זמין כרגע."],["Sharing unavailable","المشاركة غير متاحة","השיתוף אינו זמין"],["Select and copy the result","حدّد النتيجة وانسخها","סמנו והעתיקו את התוצאה"],["Start","ابدأ","התחילו"],["Step 1","الخطوة 1","שלב 1"],["Step 2","الخطوة 2","שלב 2"],["Step 3","الخطوة 3","שלב 3"],["Step 4","الخطوة 4","שלב 4"],["Step 5","الخطوة 5","שלב 5"],["Generating a new recovery code…","جارٍ إنشاء رمز استرداد جديد…","יוצרים קוד שחזור חדש…"],["Copy failed","فشل النسخ","ההעתקה נכשלה"],["Result copied","تم نسخ النتيجة","تم نسخ النتيجة"],["⭐ Level","⭐ المستوى","⭐ רמה"],["Copy full result","نسخ النتيجة كاملة","העתקת התוצאה המלאة"],["Copied ✓","تم النسخ ✓","הועתק ✓"],["Select and copy","حدّد وانسخ","סמנו והעתיקו"],["good","جيد","טוב"],["Continue →","متابعة ←","המשך ←"],["✗ Not yet —","✗ ليس بعد —","✗ עדיין לא —"],["✗ Not yet — the equation is balanced, but the coefficients can be reduced.","✗ المعادلة موزونة، لكن يمكن تبسيط المعاملات.","✗ המשוואה מאוזנת, אך ניתן לצמצם את המקדמים."],["The equation is balanced, but the coefficients can be reduced.","المعادلة موزونة، لكن يمكن تبسيط المعاملات.","המשוואה מאוזנת, אך ניתן לצמצם את המקדמים."],["✓ Correct","✓ صحيح","✓ נכון"],["Question","السؤال","שאלה"],["Today's Daily Challenge is complete.","اكتمل تحدي اليوم الكيميائي.","האתגר הכימי היומי הושלם."],["You can review your answers or come back tomorrow for a new challenge.","يمكنك مراجعة إجاباتك أو العودة غدًا لتحدٍ جديد.","אפשר לעיין בתשובות או לחזור מחר לאתגר חדש."],["Review Daily Quiz Answers","مراجعة إجابات الاختبار اليومي","סקירת תשובות החידון היומי"],["Daily Quiz Answers","إجابات الاختبار اليومي","תשובות החידון היומי"],["Share result","مشاركة النتيجة","שיתוף התוצאה"],["Copy result","نسخ النتيجة","העתקת התוצאה"],["Try again tomorrow","جرّب مجددًا غدًا","נסו שוב מחר"],["Start today's challenge","ابدأ تحدي اليوم","התחילו את אתגר היום"],["Start challenge","ابدأ التحدي","התחילו אתגר"],["Submit answer","إرسال الإجابة","שליחת תשובה"],["Next question","السؤال التالي","השאלה הבאה"],["Finish","إنهاء","סיום"],["Delete your account and saved account data? This cannot be undone.","هل تريد حذف حسابك وبيانات الحساب المحفوظة؟ لا يمكن التراجع عن ذلك.","למחוק את החשבון ואת הנתונים השמורים? לא ניתן לבטל פעולה זו."],["Enter your password to confirm account deletion:","أدخل كلمة المرور لتأكيد حذف الحساب:","הזינו את הסיסמה כדי לאשר מחיקת חשבון:"],["The server did not return a recovery code.","لم يُرجع الخادم رمز استرداد.","השרת לא החזיר קוד שחזור."],["Deleting account…","جارٍ حذف الحساب…","מוחקים את החשבון…"],["Account info","معلومات الحساب","פרטי חשבון"],["Manage your session and password securely.","أدِر جلستك وكلمة المرور بأمان.","נהלו את ההתחברות והסיסמה בצורה מאובטחת."],["View profile","عرض الملف الشخصي","צפייה בפרופיל"],["Change password","تغيير كلمة المرور","שינוי סיסמה"],["You are signed in.","لقد سجلت الدخول.","התחברתם."],["Create an account","إنشاء حساب","יצירת חשבון"],["Create an account to keep your learning progress associated with your username.","أنشئ حسابًا لربط تقدمك التعليمي باسم المستخدم الخاص بك.","צרו חשבון כדי לשייך את התקדמות הלמידה לשם המשתמש שלכם."],["Recovery code","رمز الاسترداد","קוד שחזור"],["Admin tools","أدوات الإدارة","כלי ניהול"],["Enter a username to continue.","أدخل اسم مستخدم للمتابعة.","הזינו שם משתמש כדי להמשיך."],["Current password is required.","كلمة المرور الحالية مطلوبة.","נדרשת סיסמה נוכחית."],["New password is required.","كلمة المرور الجديدة مطلوبة.","נדרשת סיסמה חדשה."],["Please enter a valid equation.","يرجى إدخال معادلة صحيحة.","הזינו משוואה תקינה."],["Please enter an equation first.","يرجى إدخال معادلة أولًا.","הזינו תחילה משוואה."],["This equation cannot be balanced with positive whole-number coefficients.","لا يمكن موازنة هذه المعادلة بمعاملات صحيحة موجبة.","לא ניתן לאזן את המשוואה הזו באמצעות מקדמים שלמים וחיוביים."],["Invalid equation","معادلة غير صالحة","משוואה לא תקינה"],["Problem found:","تم العثور على مشكلة:","נמצאה בעיה:"],["Coefficient changed from","تغيّر المعامل من","המקדם השתנה מ-"],["⚗ Chemistry","⚗ الكيمياء","⚗ כימיה"],["Equations","المعادلات","משוואות"],["👤 Account","👤 الحساب","👤 חשבון"],["Learn • Quiz • Challenges • Balance • Check","تعلّم • اختبار • تحديات • موازنة • فحص","לימוד • בוחן • אתגרים • איזון • בדיקה"],["Today's challenge","تحدّي اليوم","אתגר היום"],["Get started","ابدأ","מתחילים"],["Learning progress","التقدّم في التعلّم","התקדמות בלמידה"],["Element","العنصر","יסוד"],["Example","مثال","דוגמה"],["Atoms","الذرّات","אטומים"],["Why can't we change the subscript?","لماذا لا يمكننا تغيير الرقم السفلي؟","למה אסור לשנות את המספר התחתון?"],["A chemical equation is a short way of showing a chemical reaction. The substances you start with are called reactants, and the substances formed are called products. An arrow shows the direction from reactants to products.","المعادلة الكيميائية طريقة مختصرة لتمثيل تفاعل كيميائي. تُسمّى المواد التي نبدأ بها المتفاعلات، وتُسمّى المواد المتكوّنة النواتج. ويشير السهم إلى اتجاه التفاعل من المتفاعلات إلى النواتج.","משוואה כימית היא דרך קצרה לתאר תגובה כימית. החומרים שמהם מתחילים נקראים מגיבים, והחומרים שנוצרים נקראים תוצרים. החץ מציין את כיוון התגובה מהמגיבים לתוצרים."],["The equation tells us which substances participate in the reaction, but it is not balanced yet. A balanced equation must contain the same number of atoms of every element on both sides.","توضّح المعادلة المواد المشاركة في التفاعل، لكنها غير موزونة بعد. يجب أن تحتوي المعادلة الموزونة على العدد نفسه من ذرات كل عنصر في كلا الطرفين.","המשוואה מציינת אילו חומרים משתתפים בתגובה, אך היא עדיין אינה מאוזנת. במשוואה מאוזנת חייב להיות מספר זהה של אטומים מכל יסוד בשני צדי המשוואה."],["A chemical formula tells you which elements are present and how many atoms of each element are in one particle of the substance. A small number written after an element is a subscript.","تبيّن الصيغة الكيميائية العناصر الموجودة وعدد ذرات كل عنصر في جسيم واحد من المادة. ويُسمّى الرقم الصغير المكتوب بعد رمز العنصر رقمًا سفليًا.","נוסחה כימית מציינת אילו יסודות נמצאים בחומר וכמה אטומים מכל יסוד יש בחלקיק אחד שלו. מספר קטן הכתוב אחרי סמל יסוד נקרא מספר תחתי."],["A coefficient is placed in front of a formula and multiplies the whole formula. A subscript is part of the formula. Never change a subscript while balancing because that changes the substance.","يوضع المعامل قبل الصيغة ويضرب الصيغة كاملة. أمّا الرقم السفلي فهو جزء من الصيغة. لا تغيّر الرقم السفلي أثناء الموازنة، لأن ذلك يغيّر المادة نفسها.","מקדם נכתב לפני הנוסחה ומכפיל את הנוסחה כולה. מספר תחתי הוא חלק מהנוסחה. אין לשנות מספר תחתי במהלך האיזון, משום שהדבר משנה את החומר."],["In an ordinary chemical reaction, atoms are rearranged into new combinations. Therefore, every element must have the same total number of atoms before and after the reaction.","في التفاعل الكيميائي العادي، يُعاد ترتيب الذرات في تراكيب جديدة. لذلك يجب أن يبقى العدد الإجمالي لذرات كل عنصر متساويًا قبل التفاعل وبعده.","בתגובה כימית רגילה האטומים מסתדרים מחדש בצירופים חדשים. לכן המספר הכולל של האטומים מכל יסוד חייב להיות זהה לפני התגובה ואחריה."],["Count hydrogen: the left side has 4 H atoms and the right side has 4 H atoms. Count oxygen: the left side has 2 O atoms and the right side has 2 O atoms. The equation is balanced.","عدّ ذرات الهيدروجين: في الطرف الأيسر 4 ذرات H وفي الطرف الأيمن 4 ذرات H. وعدّ ذرات الأكسجين: في الطرف الأيسر ذرتا O وفي الطرف الأيمن ذرتا O. المعادلة موزونة.","סופרים מימן: בצד שמאל יש 4 אטומי H ובצד ימין 4 אטומי H. סופרים חמצן: בצד שמאל יש 2 אטומי O ובצד ימין 2 אטומי O. המשוואה מאוזנת."],["Make sure every element symbol and chemical formula is correct before balancing. Remember that capitalization matters: Co is cobalt, while CO represents carbon monoxide.","تأكّد من صحة رمز كل عنصر وكل صيغة كيميائية قبل الموازنة. تذكّر أن حالة الأحرف مهمة: الرمز Co هو الكوبالت، أمّا CO فيمثّل أول أكسيد الكربون.","יש לוודא שכל סמל יסוד ונוסחה כימית נכונים לפני האיזון. חשוב להבחין בין אות גדולה לקטנה: Co הוא קובלט, ואילו CO הוא פחמן חד־חמצני."],["Each coefficient multiplies the entire formula. That is why 2H₂O means two water molecules (or formula units), giving 4 H atoms and 2 O atoms without changing water into a different substance.","يضرب كل معامل الصيغة كاملة. لذلك تعني 2H₂O جزيئَين من الماء (أو وحدتَي صيغة)، أي 4 ذرات H وذرتَي O، من دون تحويل الماء إلى مادة أخرى.","כל מקדם מכפיל את הנוסחה כולה. לכן 2H₂O פירושו שתי מולקולות מים (או שתי יחידות נוסחה), ובהן 4 אטומי H ו־2 אטומי O, בלי לשנות את המים לחומר אחר."],["Polyatomic ions are groups of atoms that carry an overall charge, such as SO₄²⁻, NO₃⁻ and OH⁻. In many equations, the same polyatomic ion appears unchanged on both sides. When that happens, treating the group as one unit can make balancing easier.","יُسمّى الأيون متعدد الذرات مجموعةً من الذرات تحمل شحنة كلية، مثل SO₄²⁻ وNO₃⁻ وOH⁻. في معادلات كثيرة يظهر الأيون نفسه دون تغيير في الطرفين. عندها قد يسهل اعتبار المجموعة وحدة واحدة أثناء الموازنة.","יונים רב־אטומיים הם קבוצות אטומים בעלות מטען כולל, כגון SO₄²⁻, NO₃⁻ ו־OH⁻. במשוואות רבות אותו יון רב־אטומי מופיע ללא שינוי בשני הצדדים. במצב כזה אפשר להקל על האיזון אם מתייחסים לקבוצה כאל יחידה אחת."],["Sometimes a fractional coefficient is convenient during balancing. Fractions are temporary: after the equation is balanced, multiply every coefficient by the denominator needed to produce the smallest whole-number ratio.","أحيانًا يكون استخدام معامل كسري مفيدًا أثناء الموازنة. الكسور مؤقتة: بعد موازنة المعادلة، اضرب جميع المعاملات في المقام اللازم للحصول على أبسط نسبة من الأعداد الصحيحة.","לפעמים נוח להשתמש במקדם שברי במהלך האיזון. השברים זמניים: לאחר איזון המשוואה, מכפילים את כל המקדמים במכנה הדרוש כדי לקבל את היחס הקטן ביותר במספרים שלמים."],["For larger equations, start with an element that appears in fewer formulas. Leave hydrogen and oxygen until later when they occur in many compounds. After each coefficient change, recount every affected element.","במשוואות מורכבות יותר, התחילו ביסוד שמופיע בפחות נוסחאות. השאירו את המימן והחמצן לסוף, כאשר הם מופיעים בתרכובות רבות. לאחר כל שינוי במקדם, ספרו מחדש את כל היסודות שהושפעו.","במשוואות גדולות יותר, התחילו ביסוד שמופיע בפחות נוסחאות. השאירו את המימן והחמצן לשלבים מאוחרים יותר, כשהם מופיעים בתרכובות רבות. אחרי כל שינוי במקדם, ספרו מחדש כל יסוד שהושפע."],["For hydrocarbons reacting with oxygen, carbon is usually easiest to balance first, then hydrogen, and oxygen last. If oxygen becomes odd, a temporary fraction can simplify the calculation.","عند تفاعل الهيدروكربونات مع الأكسجين، يكون من الأسهل عادةً موازنة الكربون أولًا، ثم الهيدروجين، والأكسجين أخيرًا. إذا أصبح عدد ذرات الأكسجين فرديًا، فقد يسهّل كسر مؤقت الحساب.","בתגובת פחמימנים עם חמצן, בדרך כלל הכי קל לאזן תחילה את הפחמן, אחריו את המימן ולבסוף את החמצן. אם מספר אטומי החמצן יוצא אי־זוגי, שבר זמני עשוי לפשט את החישוב."],["Redox reactions involve oxidation and reduction. In addition to conserving atoms, ionic equations must conserve charge. Oxidation states can help identify which species are oxidized and reduced.","تتضمن تفاعلات الأكسدة والاختزال عمليتَي أكسدة واختزال. وإلى جانب حفظ عدد الذرات، يجب أن تحافظ المعادلات الأيونية على الشحنة. ويمكن أن تساعد أعداد التأكسد في تحديد الأنواع التي تتأكسد أو تختزل.","תגובות חמצון־חיזור כוללות תהליכי חמצון וחיזור. בנוסף לשימור האטומים, משוואות יוניות חייבות לשמר גם את המטען. דרגות חמצון יכולות לסייע בזיהוי המינים שעוברים חמצון וחיזור."],["For ionic equations, conserving atoms is not enough: the total charge on both sides must also match. In acidic solution, H₂O and H⁺ can be used to balance oxygen and hydrogen; electrons are used to balance charge in half-reaction methods.","في المعادلات الأيونية، لا يكفي حفظ عدد الذرات؛ بل يجب أن تتساوى الشحنة الكلية في الطرفين أيضًا. في المحلول الحمضي، يمكن استخدام H₂O وH⁺ لموازنة الأكسجين والهيدروجين، وتُستخدم الإلكترونات لموازنة الشحنة في طريقة أنصاف التفاعلات.","במשוואות יוניות, שימור האטומים אינו מספיק: גם המטען הכולל בשני הצדדים חייב להיות זהה. בתמיסה חומצית אפשר להשתמש ב־H₂O וב־H⁺ כדי לאזן חמצן ומימן; בשיטת חצאי התגובות משתמשים באלקטרונים לאיזון המטען."],["Use half-reactions systematically rather than guessing coefficients. Balance elements other than H and O first, then O with water, H with H⁺, and charge with electrons.","השתמשו בשיטת חצאי התגובות באופן שיטתי במקום לנחש מקדמים. אזנו תחילה את היסודות שאינם H או O, אחר כך את O באמצעות מים, את H באמצעות H⁺, ואת המטען באמצעות אלקטרונים.","השתמשו בשיטת חצאי התגובות באופן שיטתי במקום לנחש מקדמים. אזנו תחילה יסודות שאינם H ו־O, לאחר מכן את O באמצעות מים, את H באמצעות H⁺, ואת המטען באמצעות אלקטרונים."],["Assign an unknown coefficient to every formula, write one conservation equation for each element, and solve the resulting system. Finally, scale the solution to the smallest positive whole-number coefficients.","ضع معاملًا مجهولًا أمام كل صيغة، واكتب معادلة حفظ لكل عنصر، ثم حلّ نظام المعادلات الناتج. أخيرًا، اضرب الحل للحصول على أصغر معاملات صحيحة موجبة.","הציבו מקדם לא ידוע לפני כל נוסחה, כתבו משוואת שימור לכל יסוד ופתרו את מערכת המשוואות שמתקבלת. לבסוף, הכפילו את הפתרון כדי לקבל את המקדמים החיוביים השלמים הקטנים ביותר."],["Choose “Invite a specific player”, create a private challenge, then send the generated challenge code or share link to that player. They can join from this page.","اختر «دعوة لاعب محدد»، وأنشئ تحديًا خاصًا، ثم أرسل رمز التحدي الذي تم إنشاؤه أو رابط المشاركة إلى ذلك اللاعب. يمكنه الانضمام من هذه الصفحة.","בחרו „הזמנת שחקן מסוים”, צרו אתגר פרטי ואז שלחו לשחקן את קוד האתגר שנוצר או את קישור השיתוף. הוא יוכל להצטרף מדף זה."],["Chemical equation editor","محرّر المعادلات الكيميائية","עורך משוואות כימיות"],["e.g. Fe + O₂ → Fe₂O₃","مثال: Fe + O₂ → Fe₂O₃","לדוגמה: Fe + O₂ → Fe₂O₃"],["Chemistry equation controls","عناصر التحكم في المعادلات الكيميائية","פקדי משוואות כימיות"],["Subscript digits","الأرقام السفلية","ספרות תחתייות"],["Coefficient digits","أرقام المعاملات","ספרות המקדמים"],["Handwriting canvas","لوحة الكتابة اليدوية","משטח כתיבה בכתב יד"],["Recognized equation","المعادلة التي تم التعرّف عليها","המשוואה שזוהתה"],["Close certificate","إغلاق الشهادة","סגירת התעודה"],["practice","تدريب","תרגול"],["quiz","اختبار","בוחן"],["choice","اختيار","בחירה"],["coefficients","المعاملات","מקדמים"],["Language","اللغة","שפה"],["Search lessons, topics, or features…","ابحث في الدروس أو الموضوعات أو الميزات…","חיפוש שיעורים, נושאים או תכונות…"],["Keyboard shortcut Ctrl K","اختصار لوحة المفاتيح Ctrl K","קיצור מקלדת Ctrl K"],["Pen size:","حجم القلم:","גודל העט:"],["Eraser size:","حجم الممحاة:","גודל המחק:"],["Copy","نسخ","העתקה"],["Paste","لصق","הדבקה"],["BALANCE","موازنة","איזון"],["Equation editor","محرّر المعادلات","עורך משוואות"],["Tap a symbol to insert it","اضغط على رمز لإدراجه","לחצו על סמל כדי להוסיף אותו"],["Use normal numbers for coefficients; use the subscript buttons for formula numbers.","استخدم الأرقام العادية للمعاملات، وأزرار الأرقام السفلية لأرقام الصيغ.","השתמשו בספרות רגילות למקדמים ובכפתורי הספרות התחתייות למספרים בנוסחאות."],["✎ Handwriting input","✎ إدخال بالكتابة اليدوية","✎ קלט בכתב יד"],["🌙 Dark","🌙 الوضع الداكن","🌙 מצב כהה"],["Solo Practice and Multiplayer Challenge are separate experiences. In a challenge, both players get the same questions and race against the clock.","التدريب الفردي والتحدي متعدد اللاعبين تجربتان منفصلتان. في التحدي، يحصل اللاعبان على الأسئلة نفسها ويتنافسان ضد الوقت.","תרגול יחיד ואתגר מרובה משתתפים הם מצבים נפרדים. באתגר, שני השחקנים מקבלים את אותן השאלות ומתחרים נגד השעון."],["⚡ LIVE CHALLENGE","⚡ تحدٍ مباشر","⚡ אתגר בזמן אמת"],["Same questions • 60-second challenge • live progress • final comparison","الأسئلة نفسها • تحدٍ لمدة 60 ثانية • تقدّم مباشر • مقارنة نهائية","אותן שאלות • אתגר של 60 שניות • התקדמות בזמן אמת • השוואה סופית"],["🌐 Random opponent","🌐 خصم عشوائي","🌐 יריב אקראי"],["🎯 Invite a specific player","🎯 دعوة لاعب محدد","🎯 הזמנת שחקן מסוים"],["🔑 Join with challenge code","🔑 الانضمام برمز التحدي","🔑 הצטרפות באמצעות קוד אתגר"],["Match with an available player.","تنافس مع لاعب متاح.","התאימו את עצמכם לשחקן זמין."],["🎯 Specific player","🎯 لاعب محدد","🎯 שחקן מסוים"],["Create a private room and send the player your challenge code or link.","أنشئ غرفة خاصة وأرسل للاعب رمز التحدي أو الرابط.","צרו חדר פרטי ושלחו לשחקן את קוד האתגר או הקישור."],["⚡ Same questions","⚡ الأسئلة نفسها","⚡ אותן שאלות"],["Both players receive the identical question set.","يحصل اللاعبان على مجموعة الأسئلة نفسها.","שני השחקנים מקבלים את אותו מקבץ שאלות."],["⏱ Live competition","⏱ منافسة مباشرة","⏱ תחרות בזמן אמת"],["Timer and progress update while you solve.","يُحدَّث المؤقّت والتقدّم أثناء الحل.","הטיימר וההתקדמות מתעדכנים בזמן הפתרון."],["📊 Live score","📊 النتيجة المباشرة","📊 ניקוד בזמן אמת"],["Track your progress during the match.","تابع تقدّمك أثناء المباراة.","עקבו אחר ההתקדמות במהלך המשחק."],["🏆 Final comparison","🏆 المقارنة النهائية","🏆 השוואה סופית"],["See both scores and who won after a real challenge.","شاهد نتيجتي اللاعبين والفائز بعد انتهاء التحدي.","ראו את הניקוד של שני השחקנים ומי ניצח לאחר סיום האתגר."],["🏆 LEADERBOARD","🏆 لوحة المتصدرين","🏆 טבלת מובילים"],["Ranked by challenge solve time.","الترتيب حسب زمن حل التحدي.","הדירוג נקבע לפי זמן פתרון האתגר."],["49 questions","49 سؤالًا","49 שאלות"],["· 10 concepts: basic balancing · coefficients · diatomic elements · already-balanced equations · tricky formulas · parentheses · polyatomic ions · combustion · redox · ionic equations","· 10 مفاهيم: الموازنة الأساسية · المعاملات · العناصر ثنائية الذرة · المعادلات الموزونة مسبقًا · الصيغ الصعبة · الأقواس · الأيونات متعددة الذرات · الاحتراق · الأكسدة والاختزال · المعادلات الأيونية","· 10 נושאים: איזון בסיסי · מקדמים · יסודות דו־אטומיים · משוואות שכבר מאוזנות · נוסחאות מורכבות · סוגריים · יונים רב־אטומיים · בעירה · חמצון־חיזור · משוואות יוניות"],["Build beyond","تعلّم ما يتجاوز","להתקדם מעבר"],["the basics.","الأساسيات.","ליסודות."],["Learn the ideas you need for equations involving groups, parentheses, fractions and more complicated reactions.","تعلّم الأفكار اللازمة لموازنة معادلات تتضمن مجموعات وأقواسًا وكسورًا وتفاعلات أكثر تعقيدًا.","למדו את העקרונות הדרושים למשוואות הכוללות קבוצות, סוגריים, שברים ותגובות מורכבות יותר."],["Recognize groups that can stay together","تعرّف على المجموعات التي يمكن إبقاؤها معًا","זיהוי קבוצות שאפשר להשאיר יחד"],["OH and H₂O must still be counted atom by atom when needed. Do not change a subscript inside a chemical formula.","يجب مع ذلك عدّ ذرات OH وH₂O واحدةً واحدة عند الحاجة. لا تغيّر رقمًا سفليًا داخل صيغة كيميائية.","יש לספור את האטומים ב־OH וב־H₂O בנפרד כשצריך. אין לשנות מספר תחתי בתוך נוסחה כימית."],["How many oxygen atoms are in 2SO₄?","كم ذرة أكسجين توجد في 2SO₄؟","כמה אטומי חמצן יש ב־2SO₄?"],["What atoms are in NO₃?","ما الذرات الموجودة في NO₃؟","אילו אטומים יש ב־NO₃?"],["Why can an unchanged polyatomic group sometimes be balanced as a unit?","لماذا يمكن أحيانًا موازنة مجموعة متعددة الذرات دون تغيير كوحدة واحدة؟","מדוע אפשר לפעמים לאזן קבוצה רב־אטומית שלא השתנתה כיחידה אחת?"],["⚡ DAILY CHALLENGE","⚡ تحدّي اليوم","⚡ אתגר יומי"],["Start your learning path","ابدأ مسار التعلّم","התחילו את מסלול הלמידה"],["No challenge results yet. Be the first!","لا توجد نتائج للتحديات بعد. كن أول المشاركين!","עדיין אין תוצאות לאתגרים. היו הראשונים!"]];const M={ar:{},he:{}};for(const r of rows){M.ar[r[0]]=r[1];M.he[r[0]]=r[2]}const K='chemistryLanguage';const lang=()=>{try{return localStorage.getItem(K)||'en'}catch{return'en'}};function tr(s,l){const raw=String(s||''),k=raw.trim();if(!k||l==='en')return raw;const d=M[l]||{};if(d[k])return raw.replace(k,d[k]);if(k.startsWith('✓ Correct — '))return raw.replace('✓ Correct — ',l==='ar'?'✓ صحيح — ':'✓ נכון — ');if(k.startsWith('Coefficient for '))return raw.replace('Coefficient for ',l==='ar'?'معامل الصيغة ':'מקדם עבור ');if(k.startsWith('Answer: '))return raw.replace('Answer: ',l==='ar'?'الإجابة: ':'תשובה: ');if(k.startsWith('You can continue to '))return raw.replace('You can continue to ',l==='ar'?'يمكنك المتابعة إلى ':'אפשר להמשיך אל ');const meta=k.match(/^(Beginner|Intermediate|Advanced) · Lesson (\d+) of (\d+)$/);if(meta){const level=l==='ar'?({'Beginner':'المبتدئ','Intermediate':'المتوسط','Advanced':'المتقدم'}[meta[1]]):({'Beginner':'מתחילים','Intermediate':'ביניים','Advanced':'מתקדם'}[meta[1]]);return level+(l==='ar'?' · الدرس ':' · שיעור ')+meta[2]+(l==='ar'?' من ':' מתוך ')+meta[3]}const prerequisite=k.match(/^Question (\d+)$/);if(prerequisite)return l==='ar'?'السؤال '+prerequisite[1]:'שאלה '+prerequisite[1];if(k.startsWith('Not quite. The correct answer is: '))return raw.replace('Not quite. The correct answer is: ',l==='ar'?'ليس تمامًا. الإجابة الصحيحة هي: ':'לא בדיוק. התשובה הנכונה היא: ');const q=k.match(/^Question (\d+) of (\d+)$/);if(q)return l==='ar'?'السؤال '+q[1]+' من '+q[2]:'שאלה '+q[1]+' מתוך '+q[2];if(k.startsWith('Daily practice streak: ')){const x=k.match(/^Daily practice streak: (\d+) (day|days)(?: · Best: (\d+))?$/);if(x)return l==='ar'?'سلسلة التدريب اليومية: '+x[1]+' يوم'+(x[3]?' · أفضل نتيجة: '+x[3]:''):'סדרת התרגול היומית: '+x[1]+' ימים'+(x[3]?' · השיא: '+x[3]:'')}return raw}function scan(root){const l=lang(),w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];document.documentElement.lang=l;document.documentElement.dir=l==='en'?'ltr':'rtl';while(w.nextNode())nodes.push(w.currentNode);for(const n of nodes){const p=n.parentElement;if(!p||['SCRIPT','STYLE','NOSCRIPT','TEXTAREA','SELECT','OPTION'].includes(p.tagName)||p.closest('code,pre,[data-no-translate],.equation,.chemical-equation,.formula,.math,.site-language-control'))continue;const v=n.nodeValue||'';if(v.trim()){const t=tr(v,l);if(t!==v)n.nodeValue=t}}for(const e of root.querySelectorAll?root.querySelectorAll('[placeholder],[aria-label],[title]'):[]){for(const a of ['placeholder','aria-label','title'])if(e.hasAttribute(a)){const v=e.getAttribute(a),t=tr(v,l);if(t!==v)e.setAttribute(a,t)}}}function init(){scan(document.body);new MutationObserver(ms=>ms.forEach(m=>{if(m.type==='childList')m.addedNodes.forEach(n=>{if(n.nodeType===1)scan(n);else if(n.nodeType===3&&n.parentElement){const v=n.nodeValue,t=tr(v,lang());if(t!==v)n.nodeValue=t}})})).observe(document.body,{childList:true,subtree:true});window.addEventListener('chemistryLanguageChanged',()=>scan(document.body))}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();